// Üretilen dosya: tool/ozgun/uret.py. Kimya · Çözeltiler, derişim ve koligatif özellikler (orta).
const ozChemistry11Orta = <(String, String, List<String>, String)>[
  ('Hidrojen gazının paladyum metali içinde çözünerek depolanabilmesi, çözelti sınıflandırmasında hangi türe örnektir?', 'Gaz çözünenin katı çözücüde çözünmesi', ['Katı çözünenin sıvı çözücüde çözünmesi', 'Sıvı çözünenin gaz çözücüde çözünmesi', 'Gaz çözünenin sıvı çözücüde çözünmesi'], 'Paladyum katı, hidrojen ise gazdır. Çözücü katı olduğundan bu örnek gaz-katı çözelti türündedir.'),
  ('Bir iyonik katının suda çözünme sürecinde hangi basamak enerji açısından ekzotermiktir?', 'Su moleküllerinin iyonları sarması', ['Kristal örgüsündeki iyonların birbirinden ayrılması', 'Su moleküllerinin birbirinden uzaklaşması', 'Katının önce buharlaştırılması'], 'Örgü sökülmesi ve çözücü moleküllerinin birbirinden ayrılması enerji ister. İyon-dipol çekimlerinin kurulduğu hidratlaşma basamağı ise enerji açığa çıkarır.'),
  ('Bir tuzun kristal örgü enerjisi 700 kJ/mol (örgüyü sökmek için gerekli), iyonlarının hidratlaşma enerjisi ise 720 kJ/mol (açığa çıkan) ise tuzun çözünme entalpisi kaç kJ/mol\'dür?', '−20', ['+20', '−1420', '+1420'], 'ΔH(çözünme) = +700 + (−720) = −20 kJ/mol. Negatif değer çözünmenin ekzotermik olduğunu gösterir.'),
  ('Oktanol (C₈H₁₇OH) molekülünde –OH grubu bulunmasına rağmen suda çok az çözünür. Bunun başlıca nedeni hangisidir?', 'Uzun apolar hidrokarbon zincirinin baskın olması', ['Oktanolün iyonik bağlı olması', 'Oktanolün hidrojen bağı yapamaması', 'Oktanolün kütlesinin sudan küçük olması ve yüzer hâle gelmesi'], '–OH grubu hidrojen bağı yapabilir; ancak sekiz karbonlu apolar zincir suyla uyum sağlamaz ve çözünürlüğü sınırlar.'),
  ('Sodyum klorür, polar su moleküllerinde çözünürken heksanda çözünmez. Bu gözlem hangi çıkarıma yol açar?', 'Heksan iyonları sarıp ayıracak kadar güçlü bir etkileşim kuramaz', ['Heksanın yoğunluğu sudan büyüktür', 'NaCl heksanda tepkimeye girip çöker', 'Heksan polar bir sıvıdır'], 'İyon-dipol çekimi güçlüdür; apolar heksan ise iyonlarla ancak çok zayıf London kuvvetleri yapar. Örgüyü sökecek enerji karşılanmaz.'),
  ('Na⁺ iyonu suda çözünürken çevresindeki su moleküllerinin nasıl yönlendiği doğrudur?', 'Oksijen ucu iyona dönük olarak', ['Hidrojen ucu iyona dönük olarak', 'Moleküller rastgele, yönlenmeden', 'Moleküller iyonun içine girerek'], 'Su molekülünün oksijen ucu kısmi negatiftir ve pozitif yüklü Na⁺ iyonuna dönük dizilir; bu etkileşime iyon-dipol çekimi denir.'),
  ('CuSO₄·5H₂O bileşiğinde kütlece su yüzdesi yaklaşık kaçtır? (Cu: 63,5; S: 32; O: 16; H: 1 g/mol)', '36', ['180', '45', '56'], 'Mol kütlesi 159,5 + 90 = 249,5 g/mol\'dür. Su oranı 90 / 249,5 ≈ 0,36 yani %36\'dır.'),
  ('Na₂CO₃·10H₂O bileşiğinin 28,6 gramı ısıtılarak tüm kristal suyu uçuruluyor. Geriye kaç gram susuz Na₂CO₃ kalır? (Na₂CO₃: 106 g/mol, H₂O: 18 g/mol)', '10,6', ['18,00', '17,6', '12,0'], 'Hidratın mol kütlesi 286 g/mol\'dür; 28,6 g bu bileşik 0,1 moldür. 0,1 mol Na₂CO₃ = 10,6 g\'dır.'),
  ('Alçı taşı (CaSO₄·2H₂O) ısıtılarak kısmen susuzlaştırılıp toz hâline getirilir. Bu tozun su ile karıştırılınca sertleşmesinin nedeni nedir?', 'Yeniden kristal suyu bağlayarak sert hidrata dönüşmesi', ['Suyun buharlaşıp tuzun çökmesi', 'Kalsiyumun su ile tepkimeye girip Ca(OH)₂ ve H₂ gazı vermesi', 'Toz tanelerinin yalnız birbirine yapışması'], 'Kısmen susuz alçı su ile karışınca CaSO₄·2H₂O kristalleri yeniden oluşur. Kenetlenen iğnemsi kristaller sert bir kütle meydana getirir.'),
  ('Aşağıdaki karbonat tuzlarından hangisi suda iyi çözünür?', 'Na₂CO₃', ['CaCO₃', 'BaCO₃', 'MgCO₃'], 'Alkali metal karbonatları suda çözünür. Toprak alkali karbonatlarının (kireç taşı, mermer gibi) çözünürlüğü ise çok düşüktür.'),
  ('Magnezya sütü olarak bilinen ilaç beyaz, bulanık bir görünüme sahiptir. Bunun nedeni hangisidir?', 'Mg(OH)₂\'nin suda az çözünmesi ve katı tanecik olarak asılı kalması', ['Mg(OH)₂\'nin suda tamamen çözünmesi', 'Magnezyumun suyla tepkime verip gaz çıkarması', 'Mg(OH)₂\'nin havadaki CO₂ ile tepkimeye girip MgO oluşturması'], 'Magnezyum hidroksit suda çok az çözünür; geri kalan katı tanecikler süspansiyon oluşturarak sütümsü görüntü verir.'),
  ('Bir katının 20 °C\'deki çözünürlüğü 40 g/100 g sudur. Bu sıcaklıkta hazırlanmış 350 g doymuş çözeltide kaç gram çözünen vardır?', '100', ['140', '87,5', '40'], '100 g su + 40 g tuz = 140 g doymuş çözelti eder. 350 g çözeltide çözünen miktarı 350 × 40 / 140 = 100 g\'dır.'),
  ('Çözünürlüğü 25 g/100 g su olan bir maddenin doymuş çözeltisi kütlece yüzde kaçlıktır?', '20', ['25', '12,5', '33,3'], 'Doymuş çözeltide 100 g suya karşılık 25 g çözünen vardır; toplam 125 g\'dır. Yüzde 25 / 125 × 100 = 20\'dir.'),
  ('Bir tuzun 80 °C\'de 60 g/100 g su, 20 °C\'de 30 g/100 g su çözünürlüğü vardır. 80 °C\'de 300 g su ile hazırlanan doymuş çözelti 20 °C\'ye soğutulduğunda kaç gram tuz çöker?', '90', ['180', '60', '30'], '80 °C\'de 300 g suda 180 g tuz çözünmüştür. 20 °C\'de 300 g su 90 g tutar. Çöken miktar 180 − 90 = 90 g\'dır.'),
  ('20 °C\'de çözünürlüğü 36 g/100 g su olan NaCl\'nin doymuş çözeltisinden 136 g alınıp 50 g su buharlaştırılıyor (sıcaklık sabit). Kaç gram NaCl kristallenir?', '18', ['36', '500', '9'], '136 g çözelti 100 g su ve 36 g tuz içerir. 50 g su uçunca geriye kalan 50 g su ancak 18 g tuz çözer; 18 g tuz çöker.'),
  ('Sofra tuzu çözeltisi soğutularak tuz kristallendirilmeye çalışıldığında çok az tuz elde edilir. Bunun nedeni hangisidir?', 'NaCl\'nin çözünürlüğünün sıcaklıkla çok az değişmesi', ['NaCl\'nin suda hiç çözünmemesi', 'NaCl\'nin soğukta bozunması', 'NaCl\'nin çözünürlüğünün sıcaklıkla çok hızlı azalması'], 'NaCl\'nin çözünürlük eğrisi neredeyse yataydır. Bu nedenle tuz, soğutmayla değil buharlaştırmayla elde edilir.'),
  ('Çözünme süreci endotermik olan bir katı için sıcaklık yükseltilirse çözünürlüğü nasıl değişir? Bu sonucu hangi ilke öngörür?', 'Artar; Le Chatelier ilkesi', ['Azalır; Le Chatelier ilkesi', 'Değişmez; Dalton yasası', 'Artar; Boyle yasası'], 'Isıyı alan yönde denge kayar. Endotermik çözünme ısı aldığı için sıcaklık artışı çözünmeyi artırır.'),
  ('Sıcak bir yaz günü bir göl suyundaki balıkların su yüzeyine çıkıp solumaya çalıştığı gözleniyor. Bu olayı en iyi açıklayan neden hangisidir?', 'Sıcaklık artınca suda çözünmüş oksijen miktarının azalması', ['Suyun yoğunluğunun artması', 'Oksijenin suyla tepkime vererek hidrojen peroksit oluşturması', 'Gölde karbon dioksitin tamamen kaybolması'], 'Gazların sudaki çözünürlüğü sıcaklıkla azalır. Isınan suda daha az O₂ kalır ve canlılar oksijen sıkıntısı çeker.'),
  ('Bir gazın sudaki çözünürlüğü 2 atm basınçta 0,06 mol/L ise aynı sıcaklıkta 5 atm basınçta kaç mol/L olur? (Henry yasası)', '0,15', ['0,024', '0,30', '0,10'], 'S = k·P olduğundan k = 0,06 / 2 = 0,03 mol/(L·atm). 5 atm için S = 0,03 × 5 = 0,15 mol/L olur.'),
  ('Havadaki azotun kısmi basıncı 0,78 atm\'dir. Azotun sudaki Henry sabiti 6,0·10⁻⁴ mol/(L·atm) ise suda çözünmüş azotun derişimi yaklaşık kaç mol/L\'dir?', '4,7·10⁻⁴', ['6,0·10⁻⁴', '7,7·10⁻⁴', '7,8·10⁻³'], 'S = k·P = 6,0·10⁻⁴ × 0,78 = 4,68·10⁻⁴ ≈ 4,7·10⁻⁴ mol/L\'dir.'),
  ('Aşağıdaki gazlardan hangisinin suda çözünürlüğü, aynı koşullarda genel olarak en yüksektir?', 'Amonyak (NH₃)', ['Azot (N₂)', 'Oksijen gazı (O₂)', 'Helyum (He)'], 'Amonyak polar bir moleküldür ve su ile hidrojen bağı yapar; ayrıca suyla tepkimeye girer. Diğer gazlar apolar olduğundan suda çok az çözünür.'),
  ('Karbonlu içecek üreticileri şişelemeyi neden yüksek CO₂ basıncı altında ve soğuk sıvıyla yapar?', 'Hem basınç artışı hem soğukluk gazın çözünürlüğünü artırır', ['Soğukluk gazın çözünürlüğünü azaltır, basınç da gaz çözünürlüğünü artırır', 'CO₂ yalnızca ısıtılınca çözünür', 'Basınç şekerin çözünürlüğünü artırır'], 'Henry yasasına göre basınç arttıkça, düşük sıcaklıkta da gaz çözünürlüğü artar. Her iki etki aynı yöndedir.'),
  ('Çözünürlük değerleri 100 g su için verilen iki tuzdan A, 10 °C\'de 12 g, 60 °C\'de 52 g; B ise 10 °C\'de 35 g, 60 °C\'de 38 g çözünüyor. Karışımdan A\'yı saf olarak ayırmak isteyen biri hangi yolu izlemelidir?', 'Sıcakta doymuşa yakın çözelti hazırlayıp soğutarak A\'yı kristallendirmek', ['Çözeltiyi kuruyuncaya kadar buharlaştırmak', 'Çözeltiye basınç uygulamak', 'Çözeltiyi çalkalayıp süzmek'], 'A\'nın çözünürlüğü sıcaklıkla hızla değişirken B\'ninki neredeyse sabittir. Soğutmada A çöker, B büyük oranda çözeltide kalır.'),
  ('Kütlece %5\'lik 400 g bir şeker çözeltisinden kaç gram su buharlaştırılırsa derişim kütlece %8 olur?', '150', ['100', '250', '1200'], 'Çözünen 20 g sabittir. %8 için toplam kütle 20 / 0,08 = 250 g olmalıdır. Uçurulacak su 400 − 250 = 150 g\'dır.'),
  ('Kütlece %20\'lik 300 g ile kütlece %50\'lik 200 g aynı tür tuz çözeltisi karıştırılıyor. Karışımın kütlece yüzdesi kaçtır?', '32', ['35', '300', '40'], 'Toplam tuz 60 + 100 = 160 g, toplam kütle 500 g\'dır. Yüzde 160 / 500 × 100 = 32\'dir.'),
  ('Kütlece %40\'lık 100 g çözeltiye kaç gram su eklenirse derişim %25 olur?', '60', ['40', '75', '160'], 'Çözünen 40 g\'dır. Son çözelti 40 / 0,25 = 160 g olmalıdır. Eklenen su 160 − 100 = 60 g\'dır.'),
  ('Hacimce %70\'lik 100 mL etil alkol çözeltisinden hacimce %50\'lik çözelti hazırlamak için kaç mL su eklenmelidir? (Hacimlerin toplanabildiği varsayılacak.)', '40', ['300', '50', '20'], 'Saf alkol 70 mL\'dir. Yeni hacim 70 / 0,50 = 140 mL olmalıdır; eklenecek su 40 mL\'dir.'),
  ('Altının saflığını gösteren ayar sisteminde 24 ayar saf altındır. 22 ayar bir altın alaşımında kütlece yaklaşık yüzde kaç altın bulunur?', '91,7', ['22', '78,60', '83,3'], 'Altın oranı 22 / 24 ≈ 0,917 yani %91,7\'dir. Geri kalan kısım bakır gibi diğer metallerdir.'),
  ('Yoğunluğu 0,8 g/mL olan 125 mL etanol, 400 g suya ekleniyor. Karışımın kütlece etanol yüzdesi kaçtır?', '20', ['25', '310', '17'], 'Etanol kütlesi 125 × 0,8 = 100 g\'dır. Toplam kütle 500 g olduğundan yüzde 100 / 500 × 100 = 20\'dir.'),
  ('Yüzde derişim ifadelerinden hangisi hazırlanan çözeltinin toplam hacmi hakkında doğrudan bilgi vermez ve bu yüzden sıvı-sıvı karışımlarda hacim büzülmesi yüzünden dikkat gerektirir?', 'Hacimce yüzde', ['Kütlece yüzde', 'Kütlece ppm', 'Molalite'], 'Hacimler tam toplanmadığından, hacimce yüzde derişim karışımın son hacmi ölçülerek tanımlanmalıdır. Kütle ve molalite büzülmeden etkilenmez.'),
  ('Kütlece %98\'lik ve yoğunluğu 1,84 g/mL olan derişik sülfürik asidin (98 g/mol) molaritesi kaçtır?', '18,4', ['1,840', '9,2', '98'], '1 L çözelti 1840 g\'dır ve 1803,2 g H₂SO₄ içerir; bu 18,4 mol eder. Kısa yol: M = 10 · 98 · 1,84 / 98 = 18,4 M.'),
  ('Kütlece %63\'lük, yoğunluğu 1,4 g/mL olan nitrik asit (HNO₃: 63 g/mol) çözeltisinin molaritesi kaçtır?', '14', ['8,8', '63', '1,4'], '1 L çözeltinin kütlesi 1400 g, bunun %63\'ü 882 g HNO₃\'tür. 882 / 63 = 14 mol olduğundan derişim 14 M\'dır.'),
  ('18,4 M derişik H₂SO₄ çözeltisinden 0,1 M\'lık 500 mL çözelti hazırlamak için yaklaşık kaç mL derişik asit alınmalıdır?', '2,7', ['27', '0,27', '9,2'], 'Gerekli mol sayısı 0,1 × 0,5 = 0,05 moldür. Hacim 0,05 / 18,4 ≈ 2,7·10⁻³ L = 2,7 mL\'dir.'),
  ('Kütlece %46\'lık etanol-su çözeltisinde (etanol: 46 g/mol) etanolün molalitesi kaçtır?', '18,5', ['10', '1,000', '46'], '100 g çözeltide 46 g (1 mol) etanol ve 54 g su vardır. Molalite 1 mol / 0,054 kg ≈ 18,5 m\'dir.'),
  ('Mol kesri ve kütlece yüzde derişim için hangi ifade doğrudur?', 'Mol kesrinin birimi yoktur, kütlece yüzde ise kütle oranıdır', ['Her ikisi de mol/L birimindedir', 'Mol kesri bir kütle oranıdır, kütlece yüzde ise mol sayısı oranıdır ve birimsizdir', 'İkisi de sıcaklığa göre değişir'], 'Mol kesri iki mol sayısının oranı olduğundan birimsizdir ve sıcaklıktan bağımsızdır. Kütlece yüzde de kütle oranıdır.'),
  ('Ölçülü balonda belirli molaritede çözelti hazırlanırken katı önce az suyla çözülüp sonra su çizgiye tamamlanır. Bu uygulamanın nedeni nedir?', 'Molarite için son hacmin tam olarak ölçülmesi gerekir', ['Katının daha çok çözünmesini sağlamak', 'Çözücü kütlesini bilmek', 'Çözeltinin yoğunluğunu artırmak'], 'Molarite, çözeltinin toplam hacmine dayanır. Balondaki çizgi bu hacmi kesin belirler.'),
  ('Aynı çözeltinin sıcaklığı yükseltildiğinde molarite ve molalite için hangi ifade doğrudur?', 'Molarite genellikle hafifçe azalır, molalite değişmez', ['Molalite azalır, molarite değişmez', 'İkisi de aynı oranda artar', 'İkisi de değişmez'], 'Isınınca çözeltinin hacmi genleşir, bu yüzden molarite küçülür. Molalite ise kütle esaslıdır ve sıcaklıktan etkilenmez.'),
  ('Kütlece %20\'lik bir NaCl çözeltisinin yoğunluğu 1,15 g/mL ise 500 mL çözeltideki NaCl kütlesi kaç gramdır?', '115', ['100', '57,5', '230'], 'Çözelti kütlesi 500 × 1,15 = 575 g\'dır. NaCl miktarı 575 × 0,20 = 115 g\'dır.'),
  ('Şişe üzerinde \'5 M\' yazan bir stok çözeltiden 0,25 M\'lık 400 mL çözelti hazırlamak isteyen bir öğrenci kaç mL stok çözelti almalıdır?', '20', ['80', '8', '500'], 'M₁V₁ = M₂V₂ ifadesinden V₁ = 0,25 × 400 / 5 = 20 mL bulunur.'),
  ('100 mL 0,1 M BaCl₂ çözeltisi ile 100 mL 0,15 M Na₂SO₄ çözeltisi karıştırılıyor. Oluşan BaSO₄ çökeleğinin kütlesi kaç gramdır? (BaSO₄: 233 g/mol)', '2,33', ['3,50', '1,17', '0,233'], 'BaCl₂ 0,01 mol, Na₂SO₄ 0,015 moldür. Sınırlayıcı Ba²⁺\'dır; 0,01 mol BaSO₄ = 2,33 g çöker.'),
  ('Eşit derişimli Na₃PO₄, K₂SO₄, NaCl ve glikoz çözeltilerinin elektrik iletkenlikleri büyükten küçüğe nasıl sıralanır?', 'Na₃PO₄ > K₂SO₄ > NaCl > glikoz', ['glikoz > NaCl > K₂SO₄ > Na₃PO₄ biçiminde', 'K₂SO₄ > Na₃PO₄ > NaCl > glikoz', 'NaCl > K₂SO₄ > Na₃PO₄ > glikoz'], 'Birim formülden oluşan iyon sayıları 4, 3, 2 ve 0\'dır. Eşit derişimde iyon sayısı çoksa iletkenlik de büyüktür.'),
  ('İçme suyunun iletkenliğinin ölçülmesi, suyun hangi özelliği hakkında hızlı bilgi verir?', 'Çözünmüş iyonik madde miktarı', ['Suyun renk tonu', 'Suyun içindeki canlı bakteri sayısı ve türü', 'Suyun kaynama sıcaklığı'], 'İletkenlik, çözünmüş iyonların miktarıyla artar. Bu yüzden suyun tuzluluğunu ve genel iyon yükünü belirlemek için kullanılır.'),
  ('1 L suda 0,1 mol Al₂(SO₄)₃ çözülüyor (hacim değişimi ihmal edilecek). Çözeltideki toplam iyon derişimi kaç M\'dır?', '0,5', ['0,30', '0,2', '0,1'], 'Bir formül birimi 2 Al³⁺ ve 3 SO₄²⁻ olmak üzere 5 iyon verir. 0,1 × 5 = 0,5 M.'),
  ('Bir çözeltinin yoğunluğu ölçülerek derişimi bulunmak isteniyor. Bu yöntemin geçerli olabilmesi için hangi bilgi gereklidir?', 'Yoğunluk-derişim ilişkisinin önceden belirlenmiş olması', ['Çözeltinin rengi', 'Çözeltinin kaynama noktası', 'Kabın şekli'], 'Çözünen miktarı arttıkça yoğunluk belirli bir bağıntıyla değişir. Bu bağıntı bilinirse yoğunluktan derişim bulunur (örneğin hidrometreyle).'),
  ('25 °C\'de saf benzenin buhar basıncı 95 mmHg, saf toluenin buhar basıncı 28 mmHg\'dir. Eşit mol sayılı ideal benzen-toluen çözeltisinin toplam buhar basıncı kaç mmHg\'dir?', '61,5', ['123', '47,50', '14'], 'Raoult yasasına göre P = 0,5 × 95 + 0,5 × 28 = 47,5 + 14 = 61,5 mmHg\'dir.'),
  ('Saf A ve B sıvılarının aynı sıcaklıktaki buhar basınçları 300 ve 100 mmHg\'dir. Mol kesri 0,4 A ve 0,6 B olan ideal çözeltinin toplam buhar basıncı kaç mmHg\'dir?', '180', ['200', '140', '2200'], 'P = 0,4 × 300 + 0,6 × 100 = 120 + 60 = 180 mmHg\'dir.'),
  ('İdeal iki bileşenli sıvı karışımının kaynayan çözeltisinden çıkan buharlar yoğunlaştırılırsa elde edilen sıvı hakkında hangisi söylenebilir?', 'Buhar, daha uçucu bileşen bakımından çözeltiden daha zengindir', ['Buharın bileşimi, çözeltinin bileşimiyle her zaman tamamen aynıdır', 'Buhar, uçucu olmayan bileşen bakımından daha zengindir', 'Buhar yalnız saf su içerir'], 'Buhar basıncı yüksek olan bileşen buhar fazına daha kolay geçer. Fraksiyonlu damıtma bu zenginleşmenin tekrarına dayanır.'),
  ('6 g üre (60 g/mol) 90 g suda (18 g/mol) çözülüyor. Saf suyun buhar basıncı 51 mmHg ise çözeltinin buhar basıncı yaklaşık kaç mmHg\'dir?', '50', ['510', '1', '49'], 'Üre 0,1 mol, su 5 moldür. Su mol kesri 5 / 5,1 ≈ 0,98\'dir. P = 0,98 × 51 = 50 mmHg\'dir.'),
  ('Kapalı bir kapta yan yana saf su ve derişik şeker çözeltisi dolu iki açık kap bırakılıyor (sabit sıcaklık). Uzun süre sonra ne gözlenir?', 'Saf sudaki su azalır, şeker çözeltisinin hacmi artar', ['Şeker çözeltisinin hacmi azalır, saf sudaki su miktarı artar', 'İki kapta da hiçbir değişiklik olmaz', 'İki kap da tamamen kurur'], 'Çözeltinin buhar basıncı saf suyunkinden düşüktür. Su, buhar fazı yoluyla buhar basıncı yüksek kaptan düşük kaba taşınır.'),
  ('Etanol-su karışımı fraksiyonlu damıtmayla tekrar tekrar damıtıldığında saf etanol elde edilemez; kütlece yaklaşık %95,6 etanole ulaşılınca bileşim sabitlenir. Bu karışım için hangi terim kullanılır?', 'Azeotrop', ['Kolloid çözelti', 'Hidrat', 'Alaşım'], 'Sabit bileşimli kaynayan karışıma azeotrop denir. Buharın ve sıvının bileşimi aynı olduğundan damıtmayla daha fazla ayrılamaz.'),
  ('Pozitif sapma gösteren bir sıvı karışımı için hangisi doğrudur?', 'Gerçek buhar basıncı Raoult yasasının öngördüğünden yüksektir', ['Gerçek buhar basıncı Raoult yasasının öngördüğünden çok daha düşüktür', 'Karışım hiç buharlaşmaz', 'Buhar basıncı sıcaklıktan bağımsızdır'], 'Pozitif sapmada bileşenler arasındaki çekim zayıf olduğundan bileşenler buhara daha kolay geçer; basınç ideal değerin üstünde kalır.'),
  ('1 atm basınçta 100 °C\'de bir tuz çözeltisinin buhar basıncı 740 mmHg ölçülüyor. Bu çözelti bu sıcaklıkta kaynar mı?', 'Kaynamaz; kaynayabilmesi için sıcaklığın artması gerekir', ['Kaynar; çünkü sıcaklık 100 °C\'dir', 'Kaynar; çünkü buhar basıncı 740 mmHg\'dir', 'Hiçbir sıcaklıkta kaynamaz'], 'Kaynama için buhar basıncının dış basınca (760 mmHg) eşitlenmesi gerekir. 740 < 760 olduğundan çözelti ısıtılmaya devam edilmelidir.'),
  ('Bir öğrenci 1 kg suyun donma noktasını −18,6 °C\'ye düşürmek istiyor (Kd = 1,86 °C·kg/mol). Uçucu olmayan etilen glikolden (62 g/mol) kaç gram eklemelidir?', '620', ['310', '62', '1240'], 'ΔTd = Kd · m olduğundan m = 18,6 / 1,86 = 10 mol/kg bulunur. 10 mol × 62 g/mol = 620 g gerekir.'),
  ('0,1 m Na₃PO₄ sulu çözeltisinin donma noktası ideal davranış varsayımıyla kaç °C\'dir? (Kd = 1,86; Na₃PO₄ tamamen ayrışır)', '−0,74', ['−0,19', '−0,56', '−1,860'], 'Na₃PO₄ 4 iyon verir (i = 4). ΔTd = 1,86 × 0,1 × 4 = 0,744 °C. Donma noktası yaklaşık −0,74 °C\'dir.'),
  ('0,2 mol K₂SO₄ 400 g suda çözülmüştür (Kk = 0,52 °C·kg/mol, tam ayrışma). Çözeltinin normal kaynama noktası yaklaşık kaç °C\'dir?', '100,78', ['100,26', '100,520', '101,56'], 'Molalite 0,2 / 0,4 = 0,5 m; i = 3. ΔTk = 0,52 × 0,5 × 3 = 0,78 °C. Kaynama noktası 100,78 °C\'dir.'),
  ('Aşağıdaki sulu çözeltilerden hangisi en düşük sıcaklıkta donar? (Tam ayrışma varsayılacak)', '0,1 m Al₂(SO₄)₃', ['0,15 m CaCl₂ çözeltisi', '0,2 m NaCl', '0,3 m glikoz'], 'Etkin molaliteler: Al₂(SO₄)₃ 0,5; CaCl₂ 0,45; NaCl 0,4; glikoz 0,3. En büyük değer en çok donma noktası alçalması yapar.'),
  ('Aşağıdaki sulu çözeltilerden hangisinin normal kaynama noktası en yüksektir? (Tam ayrışma varsayılacak)', '0,15 m Na₂SO₄', ['0,2 m KNO₃', '0,1 m FeCl₃', '0,4 m glikoz çözeltisi'], 'Etkin molaliteler: Na₂SO₄ 0,45; KNO₃ 0,40; FeCl₃ 0,40; glikoz 0,40. En yüksek etkin molalite Na₂SO₄\'tedir.'),
  ('Tam ayrışması beklenen NaCl çözeltisi için ölçülen i değeri 1,9 ise ayrışma derecesi (α) kaçtır?', '0,9', ['0,19', '0,95', '1,9'], 'NaCl → Na⁺ + Cl⁻ için i = 1 + α olduğundan α = 1,9 − 1 = 0,9\'dur.'),
  ('Radyatör antifrizinin yaz aylarında da faydalı olmasının nedeni hangisidir?', 'Soğutma suyunun kaynama noktasını yükselterek aşırı ısınmada kaynamayı geciktirmesi', ['Suyun buhar basıncını artırması', 'Suyun yoğunluğunu azaltması', 'Suyun ısı kapasitesini sıfırlaması'], 'Uçucu olmayan etilen glikol hem donma noktasını düşürür hem kaynama noktasını yükseltir. Bu ikili etki yıl boyu işe yarar.'),
  ('37 °C\'de (310 K) 0,15 M NaCl çözeltisinin ozmotik basıncı yaklaşık kaç atm\'dir? (R = 0,082; NaCl tamamen ayrışır)', '7,6', ['3,8', '15', '0,76'], 'i = 2 olduğundan π = 2 × 0,15 × 0,082 × 310 ≈ 7,63 atm bulunur. Bu değer kan plazmasının ozmotik basıncına çok yakındır.'),
  ('5,85 g NaCl (58,5 g/mol) ile 1 L çözelti hazırlanıyor. 27 °C\'de ozmotik basınç yaklaşık kaç atm\'dir? (R = 0,082; i = 2)', '4,92', ['2,46', '9,84', '0,490'], 'Derişim 0,1 M\'dır. π = i·M·R·T = 2 × 0,1 × 0,082 × 300 = 4,92 atm olur.'),
  ('27 °C\'de iyonlaşmayan bir maddenin sulu çözeltisinin ozmotik basıncı 2,46 atm ölçülüyor. Çözeltinin molar derişimi kaçtır? (R = 0,082)', '0,1 M', ['0,2 M', '0,01 M', '1,0 M'], 'M = π / (R·T) = 2,46 / (0,082 × 300) = 0,1 mol/L\'dir.'),
  ('0,3 M glikoz çözeltisi ile izotonik olabilecek NaCl çözeltisinin derişimi yaklaşık kaç M\'dır? (NaCl tam ayrışır)', '0,15', ['0,3', '0,6', '0,075'], 'İzotonik çözeltilerin etkin tanecik derişimi eşittir. NaCl için i = 2 olduğundan 2 × C = 0,3 ve C = 0,15 M olur.'),
  ('Bitki hücresi saf suya konulduğunda su alsa da hayvan hücresi gibi patlamaz. Bunun nedeni nedir?', 'Sert hücre duvarının hücrenin aşırı şişmesini engellemesi', ['Bitki hücresinde ozmozun gerçekleşmemesi', 'Bitki hücresinin su geçirmeyen zarı olması', 'Hücre içinin saf su olması'], 'Bitki hücresinde içeri giren su, hücre duvarına karşı bir turgor basıncı oluşturur. Bu basınç ozmotik alımı dengelediğinde su girişi durur.'),
  ('Deniz suyu içen bir kişi susuzluğunu gidermek yerine daha da susuz kalır. Bunun ozmos açısından açıklaması nedir?', 'Deniz suyu kan plazmasına göre hipertoniktir; hücrelerden su çekilir', ['Deniz suyu hipotoniktir; hücreler şişer', 'Deniz suyu izotoniktir; kan sulanır', 'Tuz suyu böbreklerde zar oluşturur'], 'Kandan daha tuzlu su içilince dokulardan kana, oradan da böbrekler yoluyla dışarı su kaybı olur ve vücut susuzlaşır.'),
  ('Tatlı su balığı bir anda denize bırakılırsa ozmos nedeniyle ne olur?', 'Vücuttan dışarı su çıkar ve balık su kaybeder', ['Balığın vücuduna su girer', 'Balığın vücut sıvısı donar', 'Balık tuzu kılçıkla ayırır'], 'Deniz suyu balığın vücut sıvısına göre hipertoniktir. Su dışarı doğru ozmozla akar ve balık dehidre olur.'),
  ('Hemodiyaliz (kan diyalizi) cihazında kandaki üre ve fazla iyonların uzaklaştırılıp kan hücrelerinin ve proteinlerin geri bırakılması hangi ilkeye dayanır?', 'Yarı geçirgen zardan küçük moleküllerin geçip büyüklerin geçememesine', ['Kanın kaynatılmasına', 'Kanın buharlaştırılmasına', 'Kanın elektrikle ayrıştırılmasına'], 'Diyaliz zarı küçük molekülleri (üre, iyonlar, su) geçirir; hücre ve protein gibi büyük parçacıkları tutar.'),
  ('Damardan verilen %5\'lik glikoz çözeltisi (yaklaşık 0,28 M) kana göre izotonik kabul edilir. Bunun temel nedeni hangisidir?', 'Çözünen taneciklerin molar derişimlerinin kandakine yakın olması', ['Glikozun tuz olması', 'Çözeltinin pH\'ının 14 olması', 'Glikozun iyonlaşıp iki iyon vermesi'], 'İzotoniklik tanecik derişimine bağlıdır. 0,28 M glikoz, kan plazmasındaki toplam çözünen derişimine (yaklaşık 0,3 M) çok yakındır.'),
  ('Yarı geçirgen zarla ayrılmış iki bölmeden birinde 0,2 M sukroz, diğerinde 0,2 M KCl vardır. Net su akışı hakkında ne söylenebilir?', 'Sukroz bölmesinden KCl bölmesine doğru su geçer', ['KCl bölmesinden sukroz bölmesine doğru su geçer ve KCl tarafı seyrelir', 'Su geçişi olmaz', 'İki yönde eşit su geçer'], 'KCl 2 iyon verdiğinden etkin derişimi 0,4 M\'dır; sukroz iyonlaşmaz ve 0,2 M kalır. Su, düşük etkin derişimden yükseğe doğru akar.'),
  ('Evlerde kullanılan ters ozmoz arıtma cihazında çıkış suyunun musluk suyuna göre iletkenliği düşüktür. Bunun nedeni nedir?', 'Zarın çözünmüş iyonların büyük bölümünü tutması', ['Suyun içine gaz verilmesi', 'Suyun ısıtılarak damıtılması', 'Suya şeker eklenmesi'], 'Basınç altında su zardan geçerken tuz iyonları geride kalır. İyon derişimi azaldığı için iletkenlik de düşer.'),
  ('Birçok koloit çözeltisinin uzun süre kararlı kalmasında hangi etken önemlidir?', 'Tanecik yüzeylerinin aynı cins elektrik yükünü taşıyıp birbirini itmesi', ['Tanecikler arasındaki çekimin çok büyük olması', 'Taneciklerin elektriksel olarak nötr olması', 'Çözücünün gaz hâlinde olması'], 'Koloit taneciklerinin yüzeyine iyon adsorplanır ve tanecikler aynı yükü taşır. Bu itme, taneciklerin birleşip büyüyüp çökmesini engeller.'),
  ('Negatif yüklü bir As₂S₃ solünü çöktürmede aşağıdaki iyonlardan hangisi en etkilidir?', 'Al³⁺', ['Na⁺', 'Cl⁻', 'Mg²⁺ iyonu'], 'Hardy-Schulze kuralına göre sol ile zıt yüklü ve yükü büyük iyon daha etkilidir. Katyonlar arasında en yüksek yük Al³⁺\'tadır.'),
  ('Pozitif yüklü bir Fe(OH)₃ solünü çöktürmede aşağıdaki anyonlardan hangisi en etkilidir?', 'PO₄³⁻', ['Cl⁻', 'NO₃⁻', 'SO₄²⁻ iyonu'], 'Pozitif solü zıt yüklü anyonlar çöktürür. Hardy-Schulze kuralına göre iyon yükü büyüdükçe etki artar; PO₄³⁻ en etkilidir.'),
  ('Nehir sularının denize karıştığı yerlerde delta oluşumunun bir nedeni, nehrin taşıdığı koloidal kil taneciklerinin deniz suyundaki tuzlar nedeniyle çökmesidir. Bu çökme hangi olayın sonucudur?', 'Elektrolit etkisiyle koloidin pıhtılaşması', ['Süspansiyonun süzülmesi', 'Çözeltinin donması', 'Çözücünün buharlaşması'], 'Deniz suyundaki iyonlar, kil taneciklerinin yüklerini yok ederek birleşmelerini sağlar. Bu pıhtılaşmayla çökelti birikir.'),
  ('Fabrika bacalarındaki duman ve kül taneciklerinin Cottrell çökelticisiyle tutulması hangi ilkeye dayanır?', 'Aerosol taneciklerinin yüklenip elektrotta toplanmasına', ['Dumanın suda çözülmesine', 'Dumanın soğutulup buharlaştırılmasına', 'Dumanın kimyasal olarak yanmasına'], 'Yüksek gerilimle tanecikler yüklenir ve zıt yüklü levhada toplanır. Böylece baca gazındaki katı tanecikler temizlenir.'),
  ('Koloidal çözelti, filtre kâğıdı ve diyaliz zarı ile süzüldüğünde hangi sonuç beklenir?', 'Filtre kâğıdından geçer, diyaliz zarından geçemez', ['Hem filtre kâğıdından hem diyaliz zarından geçer', 'Filtre kâğıdından geçemez, ancak diyaliz zarından geçer', 'İkisinden de geçemez'], 'Filtre kâğıdının gözenekleri koloit taneciklerinden büyüktür. Diyaliz zarı ise yalnız küçük molekül ve iyonları geçirir.'),
  ('Dondurma yapımında jelatin ya da benzeri kıvam artırıcı eklenmesinin bir yararı hangisidir?', 'Büyük buz kristallerinin oluşmasını engelleyip düzgün bir yapı sağlaması', ['Dondurmanın donma noktasını 0 °C\'nin üstüne çıkarması', 'Şekeri tamamen yok etmesi', 'Hava kabarcıklarını tamamen uzaklaştırması'], 'Jelatin gibi koruyucu kolloidler kristallerin büyümesini ve birleşmesini engeller; yapı ince taneli ve pürüzsüz kalır.'),
  ('Koloidal maddelerin yüzeyinde başka maddeleri tutma (adsorpsiyon) yeteneğinin yüksek olmasının temel nedeni nedir?', 'Birim kütleye düşen yüzey alanının çok büyük olması', ['Taneciklerin çok ağır olması', 'Taneciklerin gaz olması', 'Taneciklerin iyonik olması'], 'Çok küçük boyutlu tanecikler çok büyük toplam yüzey alanı sağlar; bu yüzey, adsorpsiyon için geniş bir bölge oluşturur.'),
  ('Küçük kesiklerde kanamayı durdurmak için kullanılan şapın (ya da FeCl₃) etkisi hangi olaya dayanır?', 'Kandaki yüklü koloidal proteinlerin iyonlarla pıhtılaşması', ['Kanın buharlaşması', 'Kanın donması', 'Kanın çözünürlüğünün artması'], 'Kan, yüklü koloidal parçacıklar içerir. Al³⁺ ya da Fe³⁺ gibi yüksek yüklü iyonlar yükleri nötrleyip pıhtılaşmayı hızlandırır.'),
  ('Bir parçacık dağılımında sıvı bir ortamda dağılmış, boyutu yaklaşık 10 µm olan katı tanecikler için doğru sınıflandırma hangisidir?', 'Süspansiyon', ['Gerçek çözelti', 'Koloidal çözelti', 'Alaşım'], '10 µm = 10 000 nm\'dir ve koloit üst sınırı olan 1000 nm\'den büyüktür; bekletilince çöker ve süspansiyon sayılır.'),
  ('Süt (yağ damlacıkları su içinde) ile tereyağı (su damlacıkları yağ içinde) karşılaştırıldığında emülsiyon türleri için hangisi doğrudur?', 'Süt yağ-su (Y/S), tereyağı su-yağ (S/Y) türündedir', ['Her ikisi de aynı yağ-su türündedir', 'Süt su-yağ, tereyağı yağ-su türündedir', 'İkisi de gerçek çözeltidir'], 'Sürekli ortam sütte sudur, tereyağında yağdır. Süt Y/S, tereyağı S/Y emülsiyonudur.'),
  ('Sütün homojenizasyon işleminde süt yüksek basınçla çok ince deliklerden geçirilir. Bu işlemin amacı nedir?', 'Yağ damlacıklarını küçültüp kaymağın yüzeyde toplanmasını önlemek', ['Sütteki laktozu parçalamak', 'Sütteki suyu uzaklaştırmak', 'Sütün pH\'ını artırmak'], 'Damlacıklar küçüldükçe yüzeye çıkma eğilimleri azalır; süt uzun süre düzgün karışım olarak kalır.'),
  ('Çelikte karbon atomlarının demir atomlarının arasındaki boşluklara yerleşmesi, alaşım yapılarının hangi türüne örnektir?', 'Ara yerleşimli (arayer) alaşım', ['Yer değiştirmeli alaşım (substitusyonel) türü', 'İyonik bileşik', 'Moleküler katı'], 'Küçük karbon atomları, büyük demir atomlarının kristal örgüsündeki boşluklara sığar; bu tür alaşıma ara yerleşimli alaşım denir.'),
  ('Pirinçte çinko atomlarının bakır atomlarının örgüdeki yerlerini alması hangi alaşım türünü gösterir?', 'Yer değiştirmeli alaşım', ['Ara yerleşimli (arayer) alaşım türü', 'Moleküler alaşım', 'Kovalent ağ yapı'], 'Çinko ve bakır atom boyutları birbirine yakındır. Çinko atomları bakır atomlarının yerine geçer; buna yer değiştirmeli alaşım denir.'),
  ('Paslanmaz çeliğin paslanmaya karşı dirençli olması hangi özelliğiyle açıklanır?', 'Yüzeyde krom oksit gibi koruyucu bir tabakanın oluşması', ['İçinde hiç demir bulunmaması', 'Karbon içermemesi', 'Elektriği iletmemesi'], 'Alaşımdaki krom, havayla temas edince ince ve sıkı bir Cr₂O₃ tabakası oluşturur; bu tabaka demiri korur.'),
  ('Kalay-kurşun lehimin kullanım amacı için çok uygun olmasının nedenlerinden biri hangisidir?', 'Erime noktasının bileşen metallerin erime noktalarından düşük olması', ['Elektriği hiç iletmemesi', 'Suda çözünmesi', 'Erime noktasının çok yüksek olması'], 'Lehim alaşımı, bileşenlerinden daha düşük sıcaklıkta erir; bu sayede elektronik parçalar ısıya zarar verilmeden birleştirilebilir.'),
  ('Düşük karbonlu çelikle yüksek karbonlu çelik karşılaştırıldığında genel eğilim hangisidir?', 'Karbon oranı arttıkça çelik daha sert ve daha kırılgan olur', ['Karbon oranı arttıkça çelik daha yumuşak, daha esnek ve daha sünek olur', 'Karbon oranı çeliğin sertliğini etkilemez', 'Karbon oranı arttıkça çelik elektriği daha iyi iletir'], 'Karbon atomları demir atomlarının kaymasını zorlaştırır; sertlik artar ama süneklik azalır.'),
  ('Alaşımların elektrik iletkenliği genel olarak saf metallere göre nasıl değişir?', 'Çoğunlukla azalır', ['Her zaman belirgin artar', 'Sıfıra düşer', 'Değişmez'], 'Yabancı atomlar örgüde düzensizlik yaratır ve serbest elektronları saçar; iletkenlik genellikle saf metale göre düşer.'),
  ('Şekerli bir ip, aşırı doygun şeker çözeltisine daldırılıp bekletilince üzerinde büyük şeker kristalleri oluşur (kaya şekeri). Bu sürecin temelinde ne vardır?', 'Aşırı doygun çözeltiden fazla çözünenin ipin üzerinde kristallenmesi', ['Şekerin suyla tepkimeye girmesi', 'Suyun şekere dönüşmesi', 'Şekerin buhar hâline geçmesi'], 'Çözelti sıcakta doyurulup soğutulduğunda çözünürlük düşer; fazla şeker ip gibi bir çekirdek üzerinde kristallenir.'),
  ('Aşırı doygun sodyum asetat içeren el ısıtıcılarında metal diski bükünce çözelti kristallenip ısınır. Isının kaynağı nedir?', 'Kristallenmenin ekzotermik olması', ['Suyun buharlaşması', 'Sodyum asetatın havada yanması ve ısı vermesi', 'Metalin sürtünmesi'], 'Çözünme eğer endotermik/ekzotermik ise tersi kristallenmede ısıya dönüşür. Aşırı doygun çözeltide depolanan enerji, kristallenirken ısı olarak açığa çıkar.'),
  ('60 °C\'de doymuş hâle getirilen bir çözelti dikkatlice 20 °C\'ye soğutuluyor ve hiç kristal oluşmuyor. Bu çözelti hangi durumdadır?', 'Aşırı doygun', ['Doymamış', 'Seyreltik', 'Saf çözücü hâlinde'], 'Çözünürlük 20 °C\'de daha düşüktür; fazla çözünen kristallenmediği için çözelti kararsız aşırı doygun hâldedir.'),
  ('Doymuş NaCl çözeltisine HCl gazı geçirilince NaCl kristallerinin çökmesi hangi etkiye örnektir?', 'Ortak iyon etkisi', ['Ozmos etkisi', 'Brown hareketi etkisi', 'Tyndall etkisi'], 'HCl iyonlaşınca Cl⁻ derişimi artar. NaCl çözünürlük dengesi katı yönüne kayar ve NaCl çöker.'),
  ('Doymuş kireç suyuna katı NaOH eklenirse ne gözlenir?', 'Ca(OH)₂ çökmesi', ['Çözeltinin tamamen renksizleşmesi', 'Hidrojen gazı çıkışı', 'Çözeltinin kaynaması'], 'NaOH, OH⁻ derişimini artırır. Ca(OH)₂ çözünürlük dengesi ortak iyon etkisiyle katı yönüne kayar.'),
  ('Etanol-su karışımından etanolün kısmen ayrılmasında basit damıtma yerine fraksiyonlu damıtma kullanılmasının nedeni nedir?', 'İki sıvının kaynama noktalarının birbirine yakın olması', ['Etanolün suda çözünmemesi', 'Suyun kaynama noktasının etanolden çok daha düşük olması', 'Sıvıların farklı fiziksel hâlde olması'], 'Etanol 78 °C, su 100 °C\'de kaynar; fark küçük olduğundan tek basamaklı damıtma yeterli ayırmaz. Kolon, tekrarlı buharlaşma-yoğunlaşma sağlar.'),
  ('Reçel yapılırken şekerli meyve karışımı 100 °C\'nin üzerinde, yaklaşık 104-105 °C\'de pişirilir. Bu sıcaklık değeri hangi olayı gösterir?', 'Çözünen şeker derişimi arttıkça kaynama noktasının yükselmesini', ['Suyun donma noktasının yükselmesini', 'Şekerin süblimleşmesini', 'Meyvenin aşırı soğumasını'], 'Su buharlaşıp şeker derişimi arttıkça çözeltinin kaynama noktası yükselir; bu sıcaklık derişimin bir göstergesidir.'),
  ('Ticari sirke kütlece %5 asetik asit (60 g/mol) içerir ve yoğunluğu yaklaşık 1,01 g/mL\'dir. Bu sirkenin asetik asit molaritesi yaklaşık kaçtır?', '0,84 M', ['0,083 M', '8,4 M', '0,50 M'], '1 L sirke 1010 g\'dır ve 50,5 g asetik asit içerir. 50,5 / 60 ≈ 0,84 mol olduğundan molarite 0,84 M\'dır.'),
  ('Kütlece %3\'lük hidrojen peroksit çözeltisinin (H₂O₂: 34 g/mol) yoğunluğunu 1 g/mL alırsak molaritesi yaklaşık kaçtır?', '0,88 M', ['0,088 M', '3,0 M', '8,8 M'], '1 L çözelti 1000 g\'dır ve 30 g H₂O₂ içerir. 30 / 34 ≈ 0,88 mol; derişim 0,88 M\'dır.'),
  ('Kütlece %5 NaOCl (74,5 g/mol) içeren ve yoğunluğu 1,1 g/mL olan çamaşır suyunun molaritesi yaklaşık kaçtır?', '0,74 M', ['0,067 M', '5,0 M', '1,1 M'], '1 L çözelti 1100 g\'dır ve 55 g NaOCl içerir. 55 / 74,5 ≈ 0,74 mol; derişim 0,74 M\'dır.'),
  ('Kan şekeri düzeyi 90 mg/dL olan birinin kanındaki glikoz (180 g/mol) derişimi kaç mmol/L\'dir?', '5', ['0,5', '50', '18'], '90 mg/dL = 0,9 g/L\'dir. 0,9 g / 180 g/mol = 0,005 mol/L = 5 mmol/L olur.'),
  ('Kanda sodyum derişimi 140 mmol/L ise 100 mL kanda kaç mg Na (23 g/mol) bulunur?', '322', ['3220', '32,2', '14'], '100 mL için 14 mmol Na vardır. 14 mmol × 23 mg/mmol = 322 mg\'dır.'),
  ('Bir sürücünün kanında 0,5 g/L etanol (46 g/mol) bulunuyor. Etanol derişimi yaklaşık kaç mmol/L\'dir?', '10,9', ['23', '1,09', '0,0109'], '0,5 g / 46 g/mol = 0,01087 mol = 10,9 mmol\'dür; hacim 1 L olduğundan 10,9 mmol/L bulunur.'),
  ('Serum fizyolojik kütle/hacim oranıyla %0,9 NaCl içerir. Bu çözeltinin molaritesi yaklaşık kaçtır? (NaCl: 58,5 g/mol)', '0,15 M', ['0,015 M', '0,90 M', '1,5 M'], '1 L çözeltide 9 g NaCl vardır. 9 / 58,5 ≈ 0,154 mol olduğundan derişim yaklaşık 0,15 M\'dır.'),
  ('Akü asidi kütlece %37 H₂SO₄ içerir ve yoğunluğu 1,28 g/mL\'dir. Molaritesi yaklaşık kaçtır? (H₂SO₄: 98 g/mol)', '4,8 M', ['0,48 M', '3,8 M', '37 M'], '1 L çözelti 1280 g\'dır ve 473,6 g H₂SO₄ içerir. 473,6 / 98 ≈ 4,83 mol olduğundan derişim 4,8 M\'dır.'),
  ('Kütlece %37 H₂SO₄ içeren akü asidinin molalitesi yaklaşık kaçtır? (H₂SO₄: 98 g/mol)', '6,0 m', ['4,8 m', '0,38 m', '37 m'], '100 g çözeltide 37 g (0,378 mol) H₂SO₄ ve 63 g su vardır. Molalite 0,378 / 0,063 ≈ 6,0 m\'dir.'),
  ('Formalin kütlece %37 formaldehit içerir ve yoğunluğu yaklaşık 1,09 g/mL\'dir. 100 mL formalinde yaklaşık kaç gram formaldehit bulunur?', '40', ['37', '109', '4,0'], '100 mL formalin 109 g\'dır. Formaldehit kütlesi 109 × 0,37 ≈ 40,3 g\'dır.'),
  ('Kütlece %46 etanol içeren su-etanol çözeltisinde etanolün mol kesri kaçtır? (etanol: 46 g/mol, su: 18 g/mol)', '0,25', ['0,46', '0,50', '0,750'], '100 g çözeltide 46 g (1 mol) etanol ve 54 g (3 mol) su vardır. X(etanol) = 1 / 4 = 0,25\'tir.'),
  ('250 g suda 55,5 g CaCl₂ (111 g/mol) çözülüyor (tam ayrışma, Kd = 1,86 °C·kg/mol). Çözeltinin donma noktası yaklaşık kaç °C\'dir?', '−11,16', ['−3,72', '−5,58', '−22,320'], 'Molalite 0,5 mol / 0,25 kg = 2 m\'dir. i = 3 olduğundan ΔT = 1,86 × 2 × 3 = 11,16 °C ve donma noktası −11,16 °C olur.'),
  ('1 atm basınçta 101,04 °C\'de kaynayan sulu sukroz (342 g/mol) çözeltisinde, 1 kg suya karşılık kaç gram sukroz çözünmüştür? (Kk = 0,52 °C·kg/mol)', '684', ['342', '1026', '171'], 'ΔTk = 1,04 °C olduğundan molalite 1,04 / 0,52 = 2 m\'dir. 1 kg suda 2 mol, yani 684 g sukroz bulunur.'),
  ('Benzende (Kk = 2,53 °C·kg/mol) 200 g çözücüye 4 g naftalin (128 g/mol) ekleniyor. Kaynama noktası yükselmesi yaklaşık kaç °C olur?', '0,40', ['0,160', '1,26', '2,53'], 'Molalite 4 / 128 / 0,2 ≈ 0,156 m\'dir. ΔTk = 2,53 × 0,156 ≈ 0,40 °C\'dir.'),
  ('0,1 m MgCl₂ ile 0,3 m glikoz sulu çözeltilerinin donma noktaları için hangisi doğrudur? (MgCl₂ tam ayrışır)', 'İkisi de aynı sıcaklıkta donar', ['MgCl₂ çözeltisi daha düşük sıcaklıkta donar', 'Glikoz çözeltisi daha düşük sıcaklıkta donar', 'İkisi de 0 °C\'de donar'], 'MgCl₂ için etkin molalite 0,1 × 3 = 0,3 m\'dir; glikoz için 0,3 m\'dir. Etkin tanecik derişimi eşit olduğundan alçalmalar da eşittir.'),
  ('24,4 g BaCl₂·2H₂O (244 g/mol) tamamen kristal suyundan arındırılınca kaç gram su uçar? (H₂O: 18 g/mol)', '3,6', ['1,8', '7,2', '0,36'], '24,4 g hidrat 0,1 moldür. Her mol hidrat 2 mol su içerdiğinden 0,2 mol su = 3,6 g uçar.'),
  ('CaSO₄·2H₂O (172 g/mol) bileşiğinde kütlece su yüzdesi yaklaşık kaçtır? (H₂O: 18 g/mol)', '21', ['10,5', '36', '42'], '2 mol su 36 g\'dır. Oran 36 / 172 ≈ 0,209 yani yaklaşık %21\'dir.'),
  ('27,8 g FeSO₄·7H₂O (278 g/mol) ısıtılarak tüm suyu uçuruluyor. Kaç gram su kaybolur? (H₂O: 18 g/mol)', '12,6', ['1,8', '27,80', '126'], '27,8 g hidrat 0,1 moldür. Her formül birimi 7 mol su içerdiğinden 0,7 mol su = 12,6 g kaybolur.'),
  ('32,2 g Na₂SO₄·10H₂O (322 g/mol) suda çözülerek 200 mL çözelti hazırlanıyor. Na₂SO₄ molaritesi kaçtır?', '0,5 M', ['0,1 M', '1,0 M', '0,05 M'], '32,2 g hidrat 0,1 mol Na₂SO₄ içerir. Kristal suyu çözücüye katılır. Derişim 0,1 / 0,2 = 0,5 M\'dır.'),
  ('25 g CuSO₄·5H₂O (249,5 g/mol) ile 250 mL sulu çözelti hazırlanıyor. CuSO₄ molaritesi yaklaşık kaçtır?', '0,4 M', ['0,1 M', '0,25 M', '1,0 M'], 'Mol sayısı 25 / 249,5 ≈ 0,1\'dir. Derişim 0,1 / 0,25 = 0,4 M\'dır.'),
  ('Üç deney tüpünde 100 g su vardır; birine 0,01 mol glikoz, birine 0,01 mol NaCl, birine 0,01 mol CaCl₂ konup çözülüyor. 1 atm\'deki kaynama sıcaklıkları nasıl sıralanır?', 'CaCl₂ > NaCl > glikoz', ['glikoz > NaCl > CaCl₂', 'NaCl > CaCl₂ > glikoz', 'Üçü de aynı sıcaklıkta kaynar'], 'Etkin tanecik sayıları CaCl₂ için 0,03 mol, NaCl için 0,02 mol, glikoz için 0,01 moldür. Kütle sabit olduğundan etkin molalite büyük olanın kaynama noktası daha çok yükselir.'),
  ('Aşağıdaki özelliklerden hangisi koligatif özellik değildir?', 'Çözeltinin elektrik iletkenliği', ['Çözeltinin buhar basıncının alçalması ve kaynama noktasının yükselmesi', 'Çözeltinin donma noktasının alçalması ve donma sırasındaki sıcaklık düşüşü', 'Çözeltinin ozmotik basıncı ve zardan geçişteki su akışı'], 'Koligatif özellikler yalnız çözünen tanecik sayısına bağlıdır. İletkenlik ise taneciklerin yüküne ve hareketliliğine de bağlı olduğundan koligatif sayılmaz.'),
  ('Bir çözeltinin kaynama noktası ve donma noktası ile ilgili koligatif etkiler birlikte düşünüldüğünde sıvı hâlin sıcaklık aralığı nasıl değişir?', 'Genişler; çünkü donma noktası düşer, kaynama noktası yükselir', ['Daralır; çünkü her iki sıcaklık da çözünen eklenince birlikte artar', 'Aynı kalır; çünkü etkiler birbirini götürür', 'Yalnız üst sınır değişir ve alt sınır sabit kalır'], 'Uçucu olmayan çözünen buhar basıncını düşürerek kaynama noktasını yükseltir ve donma noktasını düşürür. Sıvı hâlin kararlı olduğu aralık böylece genişler.'),
  ('Van\'t Hoff faktörü (i) için aşağıdakilerden hangisi doğrudur?', 'Gerçek tanecik sayısının, formül birimi sayısına oranıdır', ['Çözünen kütlesinin çözelti kütlesine oranıdır', 'Çözeltinin yoğunluğunun çözücü yoğunluğuna oranıdır', 'Çözücünün mol sayısının, çözünenin mol sayısına oranının 1/i katıdır'], 'i = çözeltideki toplam tanecik sayısı / çözünen formül birimi sayısıdır. İyonlaşmayan maddeler için 1, tam ayrışan NaCl için yaklaşık 2\'dir.'),
  ('Çözünen uçucu ise çözeltinin buhar basıncı için aşağıdakilerden hangisi doğrudur?', 'Her bileşenin kısmi basıncı Raoult yasasıyla bulunur ve toplam basınç bunların toplamıdır', ['Buhar basıncı saf çözücününkinden mutlaka düşük olur', 'Yalnız çözücünün kısmi basıncı hesaba katılır', 'Çözünen buhar basıncına hiç katkıda bulunmaz'], 'İki uçucu bileşen varsa toplam basınç, kısmi basınçların toplamıdır ve saf çözücününkinden küçük ya da büyük olabilir.'),
  ('Heksan (C₆H₁₄) ile heptanın (C₇H₁₆) karışımının ideal çözeltiye çok yakın davranmasının nedeni nedir?', 'İki molekülün benzer yapıda ve London kuvvetleriyle benzer büyüklükte çekim göstermesi', ['İki molekül arasında güçlü hidrojen bağı oluşması', 'İki molekülün iyonik yapıda olması', 'İki molekülden birinin suda çözünmemesi'], 'Benzer apolar moleküllerde karışım sırasında etkileşimler hemen hiç değişmez; bu nedenle Raoult yasasına çok yakın davranılır.'),
  ('Uçucu olmayan çözünenin aynı derişimde (mol/kg) farklı iki sıvıda kaynama noktası yükselmesi değişik olur. Bunun nedeni nedir?', 'Kk sabitinin çözücüye özgü olması', ['Çözünenin her çözücüde farklı bağ yapması', 'Çözücü ne olursa olsun Kk\'nin aynı olması', 'Basıncın çözücüye göre değişmesi'], 'ΔTk = Kk · m · i bağıntısında Kk çözücünün özelliğidir. Aynı molalitede bile çözücüye göre ΔTk farklıdır.'),
  ('Buzun üzerine tuz serpilince sıcaklığın 0 °C\'nin altına inmesi, hangi iki olayın birleşiminden kaynaklanır?', 'Buzun erirken ısı alması ve tuzlu su karışımının donma noktasının düşmesi', ['Tuzun suda çözünürken çok ısı vermesi ve buzun yoğunlaşması', 'Tuzun buzu kimyasal olarak parçalaması ve suyun buharlaşması', 'Havanın sıkışması ve buzun ısınması'], 'Tuz buzun erimesini başlatır; erime ısıyı çevreden alır. Oluşan tuzlu su 0 °C\'de donamaz, bu nedenle karışımın sıcaklığı 0 °C\'nin altına iner.'),
  ('Aynı sıcaklıkta aynı hacimdeki iki çözelti yarı geçirgen bir zarla ayrılıyor. Sol bölmede 0,1 M NaCl, sağ bölmede 0,1 M CaCl₂ vardır. Zarın hangi tarafında ozmotik basınç daha büyüktür ve su akışı nasıl olur?', 'Sağ tarafta daha büyüktür; su sağa doğru akar', ['Sol tarafta daha büyüktür; su sağa doğru akar', 'İki tarafta eşittir; net su akışı olmaz', 'Sağ tarafta daha büyüktür; su sağdan sola doğru akar'], 'CaCl₂ için etkin derişim 0,3 M, NaCl için 0,2 M\'dır. Su, etkin derişimi düşük taraftan yüksek tarafa, yani sağa doğru akar.'),
  ('Çözeltilerin koligatif özelliklerinin hesaplanmasında molarite yerine molalite kullanmanın bir avantajı nedir?', 'Molalite sıcaklıkla değişmez; çünkü kütleye dayanır', ['Molalite çözeltinin hacmini hiç gerektirmediği için her zaman daha küçük çıkar', 'Molarite kullanmak yasaktır', 'Molalite yalnız gazlar için tanımlıdır'], 'Çözücü kütlesi sıcaklıktan etkilenmez; bu yüzden molalite, sıcaklık değişince sabit kalır. Hacme dayalı molarite ise genleşmeyle değişir.'),
  ('Bir öğrenci aynı molalitedeki glikoz, NaCl ve Na₃PO₄ çözeltilerinin buhar basınçlarını aynı sıcaklıkta karşılaştırıyor. Buhar basınçları için hangisi doğrudur?', 'glikoz > NaCl > Na₃PO₄', ['glikoz < NaCl < Na₃PO₄ sırasında', 'Üçü de eşittir', 'NaCl > glikoz > Na₃PO₄'], 'Etkin tanecik sayısı arttıkça çözücünün mol kesri azalır ve buhar basıncı düşer. İyon sayıları 1, 2 ve 4 olduğundan sıra glikoz > NaCl > Na₃PO₄ olur.'),
  ('Pb(NO₃)₂ çözeltisine K₂CrO₄ çözeltisi eklendiğinde hangi renkte bir çökelti oluşur?', 'Sarı', ['Beyaz', 'Siyah', 'Mavi'], 'Pb²⁺ ve CrO₄²⁻ iyonları suda az çözünen PbCrO₄\'ü verir. Bu bileşik kron sarısı adıyla bilinen sarı bir pigmenttir.'),
  ('FeCl₃ çözeltisine NaOH çözeltisi eklendiğinde oluşan çökeltinin rengi ve formülü hangisidir?', 'Kırmızımsı kahverengi, Fe(OH)₃', ['Beyaz, FeCl₂', 'Mavi, Fe(OH)₂', 'Siyah, FeS'], 'Fe³⁺ + 3 OH⁻ → Fe(OH)₃ tepkimesi kırmızımsı kahverengi çökelek verir. Çözeltideki Na⁺ ve Cl⁻ seyirci iyonlardır.'),
  ('Cu²⁺ içeren mavi çözeltiye hidrojen sülfür (H₂S) gazı geçirildiğinde hangi gözlem yapılır?', 'Siyah renkli CuS çökelmesi', ['Çözeltinin rengi koyulaşıp çökelti oluşmaz', 'Beyaz bir çökelti oluşması', 'Kırmızı bir gaz çıkışı'], 'Cu²⁺ ve S²⁻ iyonları suda çok az çözünen siyah CuS\'ü oluşturur.'),
  ('CuSO₄ çözeltisine NaOH çözeltisi eklendiğinde ilk gözlenen çökeltinin rengi ve formülü nedir?', 'Mavi, Cu(OH)₂', ['Beyaz, CuCl₂', 'Siyah, Cu₂O', 'Sarı, Cu(NO₃)₂'], 'Cu²⁺ + 2 OH⁻ → Cu(OH)₂ açık mavi jelimsi bir çökelek verir. Isıtılırsa siyah CuO\'ya dönüşebilir.'),
  ('Aşağıdaki bileşiklerden hangisi suda iyi çözünür, diğerleri ise mide asidi giderici ilaçlarda kullanılan az çözünen bileşiklerdir?', 'NaHCO₃', ['Mg(OH)₂', 'Al(OH)₃', 'CaCO₃'], 'Sodyum bikarbonat suda çözünür. Mg(OH)₂, Al(OH)₃ ve CaCO₃ ise suda az çözünür; mide asidini yavaş yavaş nötrleştirir.'),
  ('Zn²⁺ içeren bir çözeltiye S²⁻ iyonu eklendiğinde oluşan çökeltinin rengi nedir?', 'Beyaz', ['Siyah', 'Kırmızı', 'Yeşil'], 'ZnS suda çok az çözünür ve beyaz renklidir. CuS ve PbS gibi diğer birçok metal sülfüre göre farklı renk gösterir.'),
  ('Kireç taşı (CaCO₃) bölgelerinde CO₂ çözmüş yağmur suyunun zamanla çukurlar ve mağaralar oluşturması hangi tepkimeye bağlıdır?', 'CaCO₃\'ün CO₂ ve suyla çözünür Ca(HCO₃)₂ vermesi', ['CaCO₃\'ün suyla Ca(OH)₂ vermesi', 'CaCO₃\'ün yanması', 'CaCO₃\'ün erimesi'], 'CO₂ içeren su hafif asidiktir. CaCO₃ ile tepkimeye girip çözünen kalsiyum bikarbonat oluşturur.'),
  ('Geçici sertliği olan suyun kaynatılarak yumuşatılması hangi olaya dayanır?', 'Çözünmüş bikarbonatların bozunarak çözünmeyen karbonat çökeltisi vermesine', ['Kalsiyum klorürün buharlaşmasına', 'Suyun yoğunluğunun artmasına', 'Çözünmüş oksijenin artmasına'], 'Kaynatmayla Ca(HCO₃)₂ → CaCO₃ + CO₂ + H₂O olur. Karbonat çöker ve sudaki Ca²⁺ derişimi azalır.'),
  ('Kaynatmakla giderilemeyen kalıcı sertliğe, suda çözünmüş hangi tür bileşikler neden olur?', 'Kalsiyum ve magnezyumun sülfat ve klorür tuzları', ['Kalsiyum ve magnezyumun bikarbonat ve karbonat tuzları', 'Sodyum klorür ve potasyum nitrat', 'Karbon dioksit ve oksijen'], 'Sülfat ve klorür tuzları ısıtmayla bozunmaz. Bu nedenle kaynatma Ca²⁺ ve Mg²⁺ derişimini azaltmaz.'),
  ('Sert suya Na₂CO₃ (çamaşır sodası) eklenince sudaki Ca²⁺ iyonlarının azalması hangi olayla gerçekleşir?', 'Ca²⁺ iyonlarının CaCO₃ olarak çökmesiyle', ['Ca²⁺ iyonlarının gaz hâline geçmesiyle', 'Ca²⁺ iyonlarının suyla yanmasıyla', 'Ca²⁺ iyonlarının Na₂CO₃ ile alaşım yapmasıyla'], 'Ca²⁺ + CO₃²⁻ → CaCO₃ çökelmesi, sudaki Ca²⁺ miktarını azaltır ve suyu yumuşatır.'),
  ('İyon değiştirici reçinelerin su yumuşatmadaki işlevi hangisidir?', 'Çözeltideki Ca²⁺ ve Mg²⁺ iyonlarını tutup karşılığında Na⁺ iyonu vermesi', ['Suyu damıtarak buhar oluşturması', 'Suya CO₂ eklemesi', 'Suyun pH değerini 14\'e çıkarması'], 'Reçine Ca²⁺ ve Mg²⁺ iyonlarını bağlar ve yerine Na⁺ bırakır; böylece sertlik oluşturan iyonlar suyun içinde kalmaz.'),
  ('Baryum sülfatın çözünürlüğünün çok düşük olmasının sağlık açısından önemli sonucu hangisidir?', 'Çözünür baryum iyonu içermediğinden röntgende güvenle kullanılabilir', ['Baryum sülfat çok çözünür ve kana karışır', 'Baryum sülfat asitle bozunur ve zehirlidir', 'Baryum sülfat çözünürken ısı yayar'], 'BaSO₄ suda ve mide asidinde çok az çözünür; zehirli Ba²⁺ iyonu çok düşük derişimde kalır ve bu nedenle güvenle kullanılır.'),
  ('Gümüş nitrat çözeltisiyle test edilen bir su örneğinde krem renkli çökelti oluşuyorsa suda hangi iyonun bulunduğu düşünülür?', 'Br⁻', ['Cl⁻', 'I⁻', 'SO₄²⁻'], 'AgCl beyaz, AgBr krem, AgI sarı renklidir. Krem renkli çökelti bromür iyonunu gösterir.'),
  ('NaOH pelet tartılırken nem çektiği için tartım uzun sürüyor. Bu durum hazırlanan çözeltinin derişimi hakkında ne sonuç doğurur?', 'Gerçek NaOH miktarı hedeften az olduğundan derişim beklenenden düşük çıkar', ['Derişim beklenenden yüksek çıkar çünkü NaOH çoğalır', 'Derişim değişmez çünkü nem tartımı etkilemez', 'Çözelti hiç bazik olmaz'], 'Peletler nem ve CO₂ çektiğinden tartılan kütlenin bir kısmı su ve karbonattır. Gerçek NaOH mol sayısı hedeften azdır.'),
  ('Çözünmesi çok ısı veren bir katıdan standart çözelti hazırlanırken ölçülü balonun çizgiye tamamlanmasından önce çözeltinin oda sıcaklığına gelmesi beklenir. Bunun nedeni nedir?', 'Sıcak çözeltinin genleşmiş olması ve soğuyunca hacminin çizginin altına düşmesi', ['Isı, çözünenin kütlesini artırır', 'Isı, balonun camını eritir', 'Sıcak sıvı çizgiyi göstermez'], 'Sıcak çözeltide hacim büyüktür. Çizgiye tamamlanan çözelti soğuyunca küçülür; derişim hedeften fazla çıkar.'),
  ('NaOH çözeltisi neden doğrudan tartılarak kesin derişimli standart çözelti olarak kullanılamaz?', 'Nem ve CO₂ çektiği için tartılan kütlenin saf NaOH\'ı göstermemesi', ['NaOH suda çözünmediği için', 'NaOH çok az ısı çıkardığı için', 'NaOH\'ın mol kütlesinin bilinmemesi'], 'NaOH higroskopiktir ve havadaki CO₂ ile tepkimeye girer. Bu nedenle çözeltisinin kesin derişimi önce standart bir asitle titre edilerek belirlenir.'),
  ('12 M derişik HCl çözeltisinden 1 M\'lık 250 mL çözelti hazırlamak için yaklaşık kaç mL derişik çözelti çekilmelidir?', '20,8', ['12', '83', '2,080'], 'M₁V₁ = M₂V₂ eşitliğinden V₁ = 1 × 250 / 12 ≈ 20,8 mL bulunur.'),
  ('Bir çözelti üç kez art arda 1/10 oranında seyreltiliyor (her seferinde 1 hacim çözelti + 9 hacim su). Başlangıç derişimi C₀ ise son derişim nedir?', 'C₀ / 1000', ['C₀ / 30', 'C₀ / 100', 'C₀ / 10 000'], 'Her seyreltme derişimi 10 kat azaltır. Üç aşamada 10³ = 1000 kat azalır.'),
  ('0,5 M 100 mL ile 1,5 M 300 mL aynı tür çözelti karıştırılıyor. Karışımın molaritesi kaçtır?', '1,25 M', ['1,00 M', '1,50 M', '2,000 M'], 'Toplam mol 0,05 + 0,45 = 0,5 mol, toplam hacim 0,4 L\'dir. Derişim 0,5 / 0,4 = 1,25 M\'dır.'),
  ('Bir kimya laboratuvarında ölçülü pipet ile mezür karşılaştırıldığında hangisi daha duyarlı bir ölçüm sağlar ve neden?', 'Ölçülü pipet; çünkü tek bir hacmi çok küçük belirsizlikle ölçecek biçimde kalibre edilmiştir', ['Mezür; çünkü kalın olduğu için daha az hata yapar', 'İkisi de aynı duyarlılıktadır', 'Mezür; çünkü ucu çok dardır'], 'Ölçülü pipet belirli hacmi yüksek doğrulukla transfer etmek için tasarlanır. Mezürün çapı büyük olduğundan okuma belirsizliği daha fazladır.'),
  ('100 mL 0,5 M ve 200 mL 0,25 M aynı tür çözeltiler karıştırılıyor, ardından 200 mL su ekleniyor. Son derişim kaç M\'dır?', '0,2', ['0,25', '0,125', '0,4'], 'Toplam mol 0,05 + 0,05 = 0,1\'dir. Son hacim 500 mL\'dir. Derişim 0,1 / 0,5 = 0,2 M\'dır.'),
  ('Bir kimya öğrencisi 10 mL derişik çözeltiyi 90 mL suyla karıştırıp hacmin 100 mL olduğunu varsayıyor. Bu varsayım hangi çözelti türünde büyük hata yaratabilir?', 'Etanol-su gibi karışırken hacim büzülmesi gösteren çözeltilerde', ['Şeker-su gibi çok seyreltik çözeltilerde', 'Her tür sulu çözeltide eşit hata yapar', 'Gaz karışımlarında asla hata yapmaz'], 'Sıvılar karışırken hacimler her zaman toplanmaz. Etanol-su gibi güçlü etkileşimli sistemlerde toplam hacim, toplamdan küçük kalır.'),
  ('NaCl\'nin kristal örgüsünü sökmek yaklaşık +787 kJ/mol, iyonların hidratlaşması ise yaklaşık −784 kJ/mol enerji içerir. NaCl\'nin suda çözünmesi sırasında sıcaklık değişimi için ne söylenebilir?', 'Çok küçüktür; çözünme entalpisi sıfıra yakındır', ['Çözelti belirgin şekilde ısınır', 'Çözelti belirgin şekilde soğur', 'Çözelti kaynar'], 'ΔH = +787 − 784 = +3 kJ/mol olup sıfıra yakındır. Bu nedenle NaCl suda çözünürken sıcaklık çok az değişir.'),
  ('Aşağıdaki iyonlardan hangisinin hidratlaşma entalpisi mutlak değerce en büyüktür?', 'Li⁺', ['Na⁺ iyonu', 'K⁺', 'Cs⁺'], 'Aynı yüklü iyonlarda yarıçap küçüldükçe yük yoğunluğu artar ve su dipolleriyle çekim güçlenir. En küçük yarıçaplı Li⁺\'ın hidratlaşması en ekzotermiktir.'),
  ('Mg²⁺ ve Na⁺ iyonlarının hidratlaşma entalpileri karşılaştırıldığında hangisi doğrudur?', 'Mg²⁺\'ın değeri mutlak olarak çok daha büyüktür', ['Na⁺\'ın değeri mutlak olarak çok daha büyüktür, çünkü iyon daha küçüktür', 'İkisi eşittir', 'İyonlar hidratlaşmaz'], 'Mg²⁺ iki yüklü ve Na⁺\'dan küçüktür. Yük yoğunluğu çok yüksek olduğundan su moleküllerini çok daha güçlü çeker.'),
  ('Oje çıkarıcıda kullanılan asetonun oje filmini çözmesinin, suyun çözememesinin nedeni nedir?', 'Aseton, oje polimerinin polaritesine uygun organik bir çözücüdür; su ise bu polimerle yeterince etkileşemez', ['Su asetondan daha az sıcak olduğundan', 'Asetonun suyu kimyasal olarak parçalaması', 'Oje polimerinin iyonik olması'], 'Oje, organik polimer ve çözücülerden oluşur. Benzer benzeri çözer kuralı gereği orta polariteli aseton polimerle etkileşir; su etkileşemez.'),
  ('Karbon tetraklorür (CCl₄) polar bağlar içermesine rağmen suda çözünmez. Bunun nedeni nedir?', 'Simetrik yapısı nedeniyle molekülün genel olarak apolar olması', ['CCl₄\'ün suda iyonlaşması', 'CCl₄\'ün çok hafif olması', 'CCl₄\'ün hidrojen bağı yapması'], 'C–Cl bağları polar olmakla birlikte tetrahedral simetri dipol momentlerini birbirini götürür. Molekül apolar olduğundan polar suyla karışmaz.'),
  ('Alkolde çözünmüş bir ilaç damlasına su eklendiğinde bulanıklık oluşuyorsa en olası neden hangisidir?', 'Etken maddenin suda az çözünmesi nedeniyle çökmeye başlaması', ['Alkolün suya dönüşmesi', 'Etken maddenin gaz çıkarması', 'Suyun donması'], 'Alkol, apolar kısmı büyük etken maddeyi çözer. Su eklenince çözücünün polaritesi artar, çözünürlük düşer ve katı tanecikler oluşur.'),
  ('Polar bir madde, apolar bir sıvıyla karıştırıldığında çoğu zaman karışmamasının temel sebebi hangisidir?', 'Polar moleküllerin birbirini, apolar moleküllere göre çok daha güçlü çekmesi', ['Apolar sıvının kaynama noktasının çok düşük olması', 'Polar maddenin elektron vermesi', 'Apolar sıvının çok yoğun olması'], 'Polar moleküller arasındaki çekimler (dipol, hidrojen bağı), polar-apolar etkileşimden çok güçlüdür. Bu yüzden polar moleküller birbirini seçerek ayrı faz oluşturur.'),
  ('Gaz hâlindeki HCl suda çok iyi çözünür. Bu çözünürlüğün çok yüksek olmasının başlıca nedeni hangisidir?', 'Suyla iyonlaşma tepkimesi vermesi ve polar olması', ['Apolar olması', 'Yoğunluğunun çok küçük olması', 'Suyla hiç etkileşmemesi'], 'HCl polar bir moleküldür ve suyla H₃O⁺ ve Cl⁻ vererek iyonlaşır. Bu iyonlaşma çözünürlüğü çok artırır.'),
  ('Bir dalgıç yüzeyden (1 atm) yaklaşık 30 m derine iniyor; burada toplam basınç yaklaşık 4 atm\'dir. Soluduğu havanın kısmi azot basıncı yüzeye göre kaç kat artar ve kanda çözünmüş azot miktarı bu durumda nasıl değişir?', '4 kat artar; Henry yasasına göre çözünmüş azot yaklaşık 4 kat çoğalır', ['2 kat artar; çözünmüş azot yarıya iner', '4 kat artar; çözünmüş azot hiç değişmez', 'Değişmez; çözünmüş azot azalır'], 'Kısmi basınç toplam basınçla orantılı olarak 0,78 atm\'den 3,12 atm\'e çıkar. Henry yasasına göre çözünen gaz miktarı da yaklaşık 4 kat artar.'),
  ('Suyun kaynatılıp sonra kapalı kapta soğutulmasıyla içindeki çözünmüş havanın büyük bölümünün uzaklaştırılabilmesinin nedeni nedir?', 'Sıcaklık arttıkça gazların sudaki çözünürlüğünün azalması', ['Gazların suda kaynarken yeni bağ yapması', 'Suyun kaynarken hava üretmesi', 'Gazların soğukta daha az çözünmesi'], 'Kaynatma sırasında yüksek sıcaklık gaz çözünürlüğünü azaltır ve gazlar kabarcık olarak uzaklaşır. Bu nedenle kaynatılmış su, normal sudan daha az çözünmüş gaz içerir.'),
  ('Soğuk kutup sularının, tropik denizlere göre atmosferden daha çok CO₂ çözme eğilimi göstermesinin nedeni nedir?', 'Düşük sıcaklıkta gaz çözünürlüğünün daha yüksek olması', ['Kutup sularında daha fazla tuz bulunması', 'Kutup sularının yoğunluğunun daha düşük ve daha tuzlu olması', 'Kutuplarda atmosfer basıncının sıfır olması'], 'Gazların sudaki çözünürlüğü sıcaklık düştükçe artar. Soğuk sular bu nedenle CO₂\'yi daha çok çözer.'),
  ('Oral rehidrasyon tuzu çözeltilerinde şeker (glikoz) ve sodyum tuzunun birlikte bulunmasının nedeni nedir?', 'Bağırsakta sodyumla glikozun birlikte taşınması su emilimini artırır', ['Şekerin suyu buharlaştırması', 'Tuzun glikozu parçalaması', 'Glikozun sodyumu çökeltmesi'], 'Bağırsak hücrelerinde glikoz ve sodyum birlikte (eş taşıyıcıyla) emilir; bu emilim suyun ozmozla geçişini de artırır.'),
  ('Gözyaşıyla izotonik olmayan bir göz damlası ya da lens solüsyonu kullanıldığında gözde yanma ve batma hissi oluşabilir. Bunun ozmos açısından nedeni nedir?', 'Zar boyunca suyun hücrelere girip çıkması ve hücre hacminin bozulması', ['Çözeltinin kaynama noktasının yükselmesi', 'Çözeltideki gazların çözünmesi', 'Çözeltinin donması'], 'Gözyaşına göre hipotonik ya da hipertonik çözeltiler hücrelerden ozmozla su alıp verir; bu da rahatsızlık yaratır.'),
  ('Burun tıkanıklığında bazen %3\'lük tuzlu su (hipertonik) spreyleri kullanılır. Bu çözeltinin mukozadaki etkisi nasıl açıklanır?', 'Hipertonik ortam dokudan su çekerek şişmeyi azaltır', ['Hipertonik çözelti dokuya su verir', 'Tuz mukozayı yakarak yok eder', 'Çözelti buharlaşıp mukozayı soğutur'], 'Hipertonik çözelti, mukoza hücrelerinin çevresindeki sıvıya göre daha derişiktir. Su ozmozla dokudan çözeltiye geçer ve şişlik azalır.'),
  ('90 g su (18 g/mol) içinde 0,1 mol gliserin (uçucu olmayan, iyonlaşmayan) çözülüyor. 25 °C\'de saf suyun buhar basıncı 23,8 mmHg ise çözeltinin buhar basıncı yaklaşık kaç mmHg olur?', '23,3', ['23,80', '22,6', '0,5'], 'Su 5 mol, gliserin 0,1 moldür. X(su) = 5 / 5,1 ≈ 0,980\'dir. P = 0,980 × 23,8 ≈ 23,3 mmHg olur.'),
  ('Aynı sıcaklıkta saf heksan 151 mmHg, saf heptan 45 mmHg buhar basıncına sahiptir. Eşit mol sayılı ideal heksan-heptan çözeltisinin toplam buhar basıncı kaç mmHg\'dir?', '98', ['196', '75,5', '22,5'], 'P = 0,5 × 151 + 0,5 × 45 = 75,5 + 22,5 = 98 mmHg\'dir.'),
  ('Bir havuz suyunun klor derişimi 0,5 ppm olacak şekilde ayarlanmak isteniyor. 1000 L (1000 kg) suda kaç gram klor bulunmalıdır?', '0,5', ['5', '0,05', '500'], '0,5 ppm = 0,5 mg/kg\'dır. 1000 kg suda 500 mg yani 0,5 g klor bulunmalıdır.'),
  ('50 m³ hacmindeki bir havuz suyunda serbest klor derişimi 2 ppm yapılacaksa (1 L su ≈ 1 kg) gerekli klor kütlesi kaç gramdır?', '100', ['10', '1', '1000'], '50 m³ = 50 000 kg sudur. 2 ppm = 2 mg/kg olduğundan 100 000 mg = 100 g klor gerekir.'),
  ('Bir içme suyu kaynağında arsenik 10 ppb ölçülmüştür. 5 L (5 kg) bu suda kaç mikrogram arsenik vardır?', '50', ['2', '0,5', '500'], '10 ppb = 10 µg/kg\'dır. 5 kg suda 50 µg arsenik vardır.'),
  ('Bir balık örneğinde cıva derişimi 0,5 ppm ölçülmüştür. 200 g balıkta yaklaşık kaç mg cıva bulunur?', '0,1', ['0,5', '1', '0,01'], '0,5 ppm = 0,5 mg/kg\'dır. 0,2 kg balıkta 0,1 mg cıva vardır.'),
  ('Bir maden suyunda sodyum derişimi 20 mg/L\'dir. Bu derişim yaklaşık kaç mol/L\'dir? (Na: 23 g/mol)', '8,7·10⁻⁴', ['8,70·10⁻²', '8,7·10⁻⁶', '4,6·10⁻¹'], '20 mg = 0,020 g\'dır. 0,020 / 23 ≈ 8,7·10⁻⁴ mol\'dür; hacim 1 L olduğundan derişim 8,7·10⁻⁴ M\'dır.'),
  ('İçme suyunda nitrat için üst sınır olarak 50 mg/L kabul ediliyor. Bu değer yaklaşık kaç mol/L nitrat iyonuna karşılık gelir? (NO₃⁻: 62 g/mol)', '8,1·10⁻⁴', ['8,10·10⁻²', '8,1·10⁻⁶', '1,2·10⁻³'], '0,050 g / 62 g/mol ≈ 8,06·10⁻⁴ mol\'dür. Hacim 1 L olduğundan derişim yaklaşık 8,1·10⁻⁴ M\'dır.'),
  ('Hacimce %40 alkol içeren 700 mL içkideki saf alkolün (yoğunluk 0,79 g/mL) kütlesi yaklaşık kaç gramdır?', '221', ['280', '175', '5600'], 'Alkol hacmi 700 × 0,40 = 280 mL\'dir. Kütlesi 280 × 0,79 ≈ 221 g\'dır.'),
  ('Hacimce %96\'lık 100 mL etanole kaç mL su eklenirse çözelti hacimce %70\'lik olur? (Hacimlerin toplanabildiği varsayılacak)', '37', ['27', '50', '960'], 'Saf etanol 96 mL\'dir. Son hacim 96 / 0,70 ≈ 137 mL olmalıdır. Eklenecek su yaklaşık 37 mL\'dir.'),
  ('0,5 m NaOH çözeltisi hazırlamak için 750 g suda kaç gram NaOH (40 g/mol) çözülmelidir?', '15', ['20', '30', '7,5'], 'Gerekli mol sayısı 0,5 × 0,75 = 0,375\'tir. Kütle 0,375 × 40 = 15 g\'dır.'),
  ('2 molal sulu NaCl çözeltisinin 500 g suyu için kullanılan NaCl 58,5 g\'dır. Çözeltinin kütlece yüzde derişimi yaklaşık kaçtır? (NaCl: 58,5 g/mol)', '10,5', ['11,70', '5,3', '2,0'], '2 m çözeltide 500 g suda 1 mol (58,5 g) NaCl vardır. Çözelti kütlesi 558,5 g\'dır. Yüzde 58,5 / 558,5 × 100 ≈ 10,5\'tir.'),
  ('1 molal sulu çözeltide çözünenin mol kesri yaklaşık kaçtır? (Su: 18 g/mol)', '0,018', ['0,18', '0,0018', '0,50'], '1 kg su yaklaşık 55,5 moldür. X(çözünen) = 1 / (1 + 55,5) ≈ 0,018\'dir.'),
  ('Kütlece %36,5\'lik HCl çözeltisinin (36,5 g/mol) molalitesi yaklaşık kaçtır?', '15,7', ['10', '1,0', '36,50'], '100 g çözeltide 36,5 g (1 mol) HCl ve 63,5 g su vardır. Molalite 1 / 0,0635 ≈ 15,7 m\'dir.'),
  ('KNO₃\'ün çözünürlüğü 40 °C\'de 64, 80 °C\'de 169 g/100 g sudur. 80 °C\'de 100 g su ile doymuş çözelti hazırlanıp 40 °C\'ye soğutulursa kaç gram tuz çöker?', '105', ['64', '169', '2330'], '80 °C\'de 169 g tuz çözünmüştür; 40 °C\'de 100 g su 64 g tutar. Çöken miktar 169 − 64 = 105 g\'dır.'),
  ('KNO₃\'ün 100 g sudaki çözünürlüğü 0, 20, 40, 60 ve 80 °C\'de sırasıyla 13, 32, 64, 110 ve 169 g\'dır. Hangi sıcaklık aralığında çözünürlük artışı en büyüktür?', '60 °C - 80 °C', ['0 °C - 20 °C', '200 °C - 40 °C', '40 °C - 60 °C'], 'Artışlar sırasıyla 19, 32, 46 ve 59 g\'dır. En büyük artış 60-80 °C aralığındadır.'),
  ('KNO₃\'ün çözünürlüğü 40 °C\'de 64, 60 °C\'de 110 g/100 g sudur. 100 g suda 80 g KNO₃\'ün tamamının çözünmesi için sıcaklık en az hangi aralıkta olmalıdır?', '40 °C ile 60 °C arasında', ['0 °C ile 20 °C arasında', '20 °C ile 40 °C arasında bir sıcaklıkta', '60 °C\'nin üstünde'], '80 g KNO₃, 40 °C\'deki çözünürlük olan 64 g\'dan fazladır ama 60 °C\'deki 110 g\'ın altındadır. Çözünürlük 80 g\'a bu iki sıcaklık arasında ulaşır.'),
  ('20 °C\'de KNO₃\'ün çözünürlüğü 32 g/100 g sudur. Bu sıcaklıkta 264 g doymuş çözeltiden 100 g su buharlaştırılırsa kaç gram KNO₃ kristallenir?', '32', ['64', '100', '16'], '264 g doymuş çözelti 200 g su ve 64 g tuz içerir. 100 g su buharlaşınca geride kalan 100 g su yalnız 32 g tuz tutar; 32 g kristallenir.'),
  ('100 mL 1 M HCl çözeltisine fazla CaCO₃ ekleniyor. Normal koşullarda (NK) oluşan CO₂ hacmi kaç litredir?', '1,12', ['2,24', '0,56', '0,112'], 'CaCO₃ + 2 HCl → CaCl₂ + CO₂ + H₂O. 0,1 mol HCl\'den 0,05 mol CO₂ oluşur. NK\'de 0,05 × 22,4 = 1,12 L\'dir.'),
  ('0,5 M 200 mL CuSO₄ çözeltisine fazla Zn tozu ekleniyor. Tepkime tamamlanınca oluşan bakır kütlesi kaç gramdır? (Cu: 63,5 g/mol)', '6,35', ['12,7', '3,180', '63,5'], 'Zn + Cu²⁺ → Zn²⁺ + Cu. Cu²⁺ 0,1 moldür; 0,1 mol Cu = 6,35 g oluşur.'),
  ('20 mL su örneğine fazla AgNO₃ eklenip oluşan AgCl çökeleği süzülüp kurutulduğunda 0,287 g tartılıyor (AgCl: 143,5 g/mol). Suyun Cl⁻ derişimi kaç M\'dır?', '0,1', ['0,01', '1,0', '0,2'], 'AgCl 0,287 / 143,5 = 0,002 moldür; bu kadar Cl⁻ vardır. Derişim 0,002 / 0,020 = 0,1 M\'dır.'),
  ('Bir su örneğine fazla BaCl₂ eklenerek 0,466 g BaSO₄ (233 g/mol) elde ediliyor. Örnekteki sülfat iyonunun kütlesi kaç gramdır? (SO₄²⁻: 96 g/mol)', '0,192', ['0,466', '0,0960', '0,233'], 'BaSO₄ 0,466 / 233 = 0,002 moldür; bu kadar SO₄²⁻ vardır. Kütle 0,002 × 96 = 0,192 g\'dır.'),
  ('50 mL 0,2 M Na₂CO₃ ile 50 mL 0,2 M CaCl₂ çözeltileri karıştırılıyor. Oluşan CaCO₃ (100 g/mol) çökeleğinin kütlesi kaç gramdır?', '1,0', ['2,0', '0,50', '10'], 'Na₂CO₃ 0,01 mol, CaCl₂ 0,01 moldür. Tepkime 1:1 oranında olduğundan 0,01 mol CaCO₃ oluşur; kütlesi 1,0 g\'dır.'),
  ('2,7 g Al (27 g/mol) ile 1 M HCl çözeltisinin tam tepkimesi (2 Al + 6 HCl → 2 AlCl₃ + 3 H₂) için kaç mL HCl çözeltisi gerekir?', '300', ['100', '600', '1500'], 'Al 0,1 moldür. 2 Al\'ye 6 HCl gerektiğinden 0,3 mol HCl lazımdır. 0,3 mol / 1 M = 0,3 L = 300 mL\'dir.'),
  ('Bir gümüş sülfat çözeltisi doymuş olduğu hâlde çok seyreltik olabilir. Bu durum hangi iki kavramın birbirinden bağımsız olduğunu gösterir?', 'Doygunluk ile derişikliğin', ['Çözünürlük ile sıcaklık değişiminin', 'Molarite ile molalitenin', 'Çözücü ile çözünenin'], 'Doygunluk, çözeltinin o sıcaklıkta alabileceği en çok çözüneni içermesidir. Çözünürlüğü çok düşük bir tuzun doymuş çözeltisi bile seyreltik kalır.'),
  ('Metanol, etanol ve propanol suyla her oranda karışırken 1-bütanolün kısmen, 1-pentanolün ise çok az çözünmesinin nedeni nedir?', 'Karbon sayısı arttıkça apolar hidrokarbon zincirinin etkisinin büyümesi', ['Alkollerin OH grubunun kaybolması', 'Karbon sayısı arttıkça polaritenin artması', 'Büyük alkollerin iyonik olması'], '–OH grubu suyla hidrojen bağı yapar; zincir uzadıkça apolar kısım baskın olur ve su moleküllerinin düzenini bozar. Bu yüzden çözünürlük azalır.'),
  ('Çelikte karbon oranı kütlece yaklaşık %2\'nin altındadır. Karbon oranı %2\'yi aşan ve daha kırılgan olan demir-karbon alaşımı hangisidir?', 'Dökme demir', ['Paslanmaz çelik', 'Pirinç', 'Bronz'], 'Dökme demirde karbon yaklaşık %2-4 kadardır. Sert ve dökülebilir ancak kırılgandır.'),
  ('Alaşımlar için hangi ifade doğrudur?', 'Bileşenlerin kimyasal özelliklerini koruduğu homojen karışımlardır ve bileşimleri değişebilir', ['Sabit bileşimli saf bileşiklerdir', 'Heterojen karışımlardır', 'Mutlaka iyonik bağlıdır'], 'Alaşımlar metalik bağlı katı çözeltilerdir; bileşenlerin oranı belirli sınırlar içinde değişebilir. Bu yüzden bileşik değil, karışım sayılır.'),
  ('Hardy-Schulze kuralına göre negatif yüklü As₂S₃ solünü pıhtılaştırmak için gereken en küçük derişim (eşik) bakımından NaCl, MgCl₂ ve AlCl₃ nasıl sıralanır?', 'AlCl₃ < MgCl₂ < NaCl', ['NaCl < MgCl₂ < AlCl₃ sırasıyla', 'MgCl₂ < NaCl < AlCl₃', 'AlCl₃ = MgCl₂ = NaCl'], 'Zıt yüklü iyonun yükü büyüdükçe pıhtılaştırma etkisi artar; Al³⁺ çok az, Na⁺ ise en çok derişim gerektirir.'),
  ('Demir(III) hidroksit solündeki fazla Cl⁻ ve H⁺ iyonlarını sol taneciklerinden ayırmak için hangi yöntem kullanılır?', 'Diyaliz', ['Damıtma', 'Süzme', 'Mıknatısla ayırma'], 'Diyaliz zarı küçük iyonları geçirir ama koloit taneciklerini tutar. Sol, saf suya karşı diyaliz zarı içinde bekletildiğinde iyonlar uzaklaşır.'),
  ('Kan için doğru sınıflandırma hangisidir?', 'Hücrelerin sıvı plazmada dağıldığı, koloidal proteinler içeren heterojen sistem', ['Tek bileşenli saf sıvı', 'Gerçek çözelti', 'Gaz karışımı'], 'Kan hücreler (süspansiyon) ve plazma proteinleri (koloidal) içerir. Bu yüzden homojen bir çözelti değildir.'),
  ('Çok yüksek hızda dönen ultrasantrifüjlerle koloidal parçacıkların ayrılabilmesinin nedeni nedir?', 'Çok büyük merkezkaç ivmesinin parçacıkları yoğunluk ve boyut farkına göre çöktürmesi', ['Işığın parçacıkları eritmesi', 'Parçacıkların elektron kaybetmesi', 'Santrifüjün sıcaklığı azaltması'], 'Normal yerçekimiyle çökmeyen koloit parçacıkları, çok büyük dönme ivmesinde sıvıdan ayrılarak dibe çöker.'),
  ('Saf olmayan bir katının erime noktası aralık hâlinde ölçülürken saf maddelerinki keskin bir değerdir. Bu fark çözeltiler için hangi sonuca bağlanır?', 'Çözünen madde varlığı erime noktasını düşürür ve erime aralığını genişletir', ['Çözelti erime noktasını yükseltir', 'Çözelti hiç erimez', 'Çözelti her zaman daha hızlı donar'], 'Safsızlıklar (çözünen), erime noktasını koligatif etkiyle düşürür ve geçişi geniş bir sıcaklık aralığına yayar.'),
  ('Kütlece %20\'lik 200 g şeker çözeltisine 50 g şeker ve 50 g su ekleniyor. Yeni çözeltinin kütlece yüzdesi kaçtır?', '30', ['25', '350', '20'], 'Başlangıçta 40 g şeker vardır. Son durumda 90 g şeker, 300 g çözelti olur. Yüzde 90 / 300 × 100 = 30\'dur.'),
  ('20 °C\'de çözünürlüğü 36 g/100 g su olan NaCl\'nin doymuş çözeltisi kütlece yüzde kaç NaCl içerir?', '26,5', ['36', '31,50', '20'], '100 g su ile 36 g tuz 136 g çözelti verir. Yüzde 36 / 136 × 100 ≈ 26,5\'tir.'),
  ('Kütlece %30\'luk 500 g çözeltiyi %20\'lik yapmak için kaç gram su eklenmelidir?', '250', ['1500', '200', '100'], 'Çözünen 150 g\'dır. %20 için toplam kütle 150 / 0,20 = 750 g olmalıdır. Eklenecek su 250 g\'dır.'),
  ('Hacimce %15\'lik 300 mL ve hacimce %40\'lık 200 mL iki etanol-su çözeltisi karıştırılıyor (hacimlerin toplanabildiği varsayılacak). Karışımın hacimce yüzdesi kaçtır?', '25', ['27,5', '30', '20'], 'Alkol hacimleri 45 + 80 = 125 mL, toplam hacim 500 mL\'dir. Yüzde 125 / 500 × 100 = 25\'tir.'),
  ('Kütlece %10\'luk şekerli su hazırlamak için 180 g suda kaç gram şeker çözülmelidir?', '20', ['18', '10', '200'], 'x / (x + 180) = 0,10 denkleminden 0,9x = 18 ve x = 20 g bulunur.'),
  ('Kütlece %40\'lık 200 g bir çözeltinin yarısı dökülüp yerine aynı kütlede saf su ekleniyor. Yeni derişim kütlece yüzde kaç olur?', '20', ['10', '30', '400'], '100 g çözelti %40\'lık olduğundan 40 g çözünen kalır. Çözelti 200 g olduğundan yüzde 40 / 200 × 100 = 20\'dir.'),
  ('200 mL 0,1 M Na₂SO₄ ile 300 mL 0,2 M NaCl çözeltileri karıştırılıyor. Karışımdaki Na⁺ derişimi kaç M\'dır?', '0,2', ['0,15', '0,3', '0,1'], 'Na⁺: 0,04 + 0,06 = 0,10 mol. Hacim 0,5 L olduğundan 0,2 M\'dır.'),
  ('100 mL 0,1 M AlCl₃ ile 100 mL 0,2 M MgCl₂ çözeltileri karıştırılıyor. Cl⁻ derişimi kaç M olur?', '0,35', ['0,300', '0,50', '0,70'], 'Cl⁻: 0,03 + 0,04 = 0,07 mol. Hacim 0,2 L\'dir. Derişim 0,35 M\'dır.'),
  ('11,1 g CaCl₂ (111 g/mol) suda çözülüp 500 mL çözelti hazırlanıyor. Cl⁻ derişimi kaç M\'dır?', '0,4', ['0,2', '0,8', '0,10'], 'CaCl₂ 0,1 moldür; 0,2 mol Cl⁻ içerir. Derişim 0,2 / 0,5 = 0,4 M\'dır.'),
  ('0,5 M 100 mL K₂SO₄ çözeltisine 400 mL su ekleniyor. K⁺ derişimi kaç M olur?', '0,2', ['0,10', '0,5', '1,0'], 'K⁺ başlangıçta 1,0 M × 0,1 L = 0,1 moldür. Son hacim 0,5 L olduğundan 0,2 M olur.'),
  ('0,4 M 100 mL NaOH ile 0,1 M 300 mL NaOH çözeltileri karıştırılıyor. Son derişim kaç M\'dır?', '0,175', ['0,2500', '0,20', '0,15'], 'Toplam mol 0,04 + 0,03 = 0,07\'dir. Hacim 0,4 L\'dir. Derişim 0,07 / 0,4 = 0,175 M\'dır.'),
  ('7,45 g KCl (74,5 g/mol) ile 250 mL çözelti hazırlanıyor. K⁺ derişimi kaç M\'dır?', '0,4', ['0,1', '0,04', '4'], 'KCl 0,1 moldür; 0,25 L\'de derişim 0,4 M\'dır. Her KCl 1 K⁺ verdiğinden K⁺ da 0,4 M\'dır.'),
  ('100 mL 1 M NaCl çözeltisi ile 200 mL 0,4 M CaCl₂ çözeltisi karşılaştırıldığında hangisinde daha fazla mol Cl⁻ bulunur?', 'CaCl₂ çözeltisinde', ['NaCl çözeltisinde', 'İkisinde eşit', 'Karşılaştırma yapılamaz'], 'NaCl çözeltisinde 0,1 mol Cl⁻, CaCl₂ çözeltisinde 0,2 × 0,4 × 2 = 0,16 mol Cl⁻ vardır.'),
  ('100 mL 0,1 M Na₃PO₄ çözeltisi ile 100 mL 0,2 M NaCl çözeltisindeki toplam iyon mol sayıları arasındaki ilişki nedir?', 'Eşittir', ['Na₃PO₄ çözeltisinde iki kat fazladır', 'NaCl çözeltisinde iki kat fazladır', 'Na₃PO₄ çözeltisinde yarısı kadardır'], 'Na₃PO₄: 0,01 mol × 4 iyon = 0,04 mol. NaCl: 0,02 mol × 2 iyon = 0,04 mol. Toplam iyon sayıları eşittir.'),
  ('100 mL 0,2 M ile 100 mL 0,4 M glikoz çözeltileri karıştırılıyor. 27 °C\'de karışımın ozmotik basıncı yaklaşık kaç atm\'dir? (R = 0,082)', '7,38', ['2,46', '4,92', '14,80'], 'Karışım derişimi (0,02 + 0,04) / 0,2 = 0,3 M\'dır. π = 0,3 × 0,082 × 300 = 7,38 atm\'dir.'),
  ('Aynı çözeltinin ozmotik basıncı 300 K\'den 330 K\'e ısıtılınca (derişim sabit) yaklaşık kaç katına çıkar?', '1,1', ['0,91', '1,9', '1,5'], 'π, mutlak sıcaklıkla orantılıdır. 330 / 300 = 1,1 kat artar.'),
  ('Aynı sıcaklıkta aşağıdaki sulu çözeltilerden hangisinin ozmotik basıncı en büyüktür?', '0,1 M Al₂(SO₄)₃', ['0,25 M glikoz çözeltisi', '0,15 M NaCl', '0,1 M CaCl₂'], 'Etkin derişimler: Al₂(SO₄)₃ için 0,5; glikoz için 0,25; NaCl için 0,3; CaCl₂ için 0,3 M\'dır. En büyük değer Al₂(SO₄)₃\'tedir.'),
  ('Yarı geçirgen zarla ayrılmış A (0,1 M NaCl) ve B (0,2 M glikoz) bölmeleri için hangisi doğrudur? (Aynı sıcaklık)', 'Etkin derişimler eşittir; net su akışı olmaz', ['Su A\'dan B\'ye akar', 'Su B\'den A\'ya akar', 'Zarın iki yanına da NaCl geçer'], 'NaCl için etkin derişim 0,2 M, glikoz için 0,2 M\'dır. İki taraf izotonik olduğundan net su geçişi olmaz.'),
  ('Ozmotik basınç değeri aşağıdakilerden hangisine bağlı değildir?', 'Çözünen taneciğin kimyasal adına', ['Çözünen tanecik molaritesine', 'Mutlak sıcaklığa', 'Van\'t Hoff faktörüne'], 'π = i·M·R·T bağıntısı yalnızca tanecik derişimi, sıcaklık ve i\'ye bağlıdır; çözünenin adı doğrudan görünmez.'),
  ('Doygun NaCl çözeltisine radyoaktif işaretli NaCl kristali atılıyor. Bir süre sonra işaretli iyonların çözeltide bulunması neyi gösterir?', 'Çözünme ve kristallenmenin aynı hızda sürdüğünü, yani dinamik dengeyi', ['Çözünmenin tamamen durduğunu', 'Kristallenmenin başladığını ve çözünmenin bittiğini', 'NaCl\'nin bozunup yeni element oluşturduğunu'], 'Doygun çözeltide çözünme ve kristallenme aynı hızla sürer. İşaretli iyonlar çözeltiye geçerken eşit sayıda iyon kristale geri döner.'),
  ('İdeal iki gazın aynı kapta karışması kendiliğinden gerçekleşir ve neredeyse hiç ısı alışverişi olmaz. Bu karışmayı yürüten etken hangisidir?', 'Düzensizliğin (entropinin) artması', ['Karışımın enerjisinin büyük ölçüde azalması', 'Moleküller arası güçlü çekim', 'Moleküllerin birbirine bağ yapması'], 'İdeal gazlar arasında çekim yoktur; karışma entalpisi sıfırdır. Karışmayı entropi artışı sağlar.'),
  ('Çözünürlüğü sıcaklık yükseldikçe azalan bir katı için çözünme süreci hakkında ne söylenebilir?', 'Çözünme ekzotermiktir', ['Çözünme endotermiktir', 'Çözünme ısı alışverişi olmadan gerçekleşir', 'Çözünme hiç gerçekleşmez'], 'Le Chatelier ilkesine göre sıcaklık artışı ısıyı alan yöne dengeyi kaydırır. Çözünürlüğün azalması, çözünmenin ısı veren (ekzotermik) olduğunu gösterir.'),
  ('Çözünme hızı çözelti doygunluğa yaklaştıkça nasıl değişir?', 'Azalır; çünkü kristallenme hızı çözünme hızına yaklaşır', ['Artar; çünkü çözünen miktarı artar', 'Sabit kalır', 'Doygunlukta en yüksek değerine ulaşır'], 'Çözelti derişimi arttıkça kristallenme hızı artar ve net çözünme hızı azalır. Doygunlukta net çözünme sıfırdır.'),
  ('20 °C\'de KNO₃\'ün çözünürlüğü 32 g/100 g sudur. Bu sıcaklıktaki doymuş çözelti kütlece yaklaşık yüzde kaç KNO₃ içerir?', '24,2', ['32', '30', '19,20'], 'Çözelti kütlesi 132 g\'dır. Yüzde 32 / 132 × 100 ≈ 24,2\'dir.'),
  ('Bir doymuş çözeltiden 130 g alınıp tamamen buharlaştırılınca 30 g katı kalıyor. Bu katının o sıcaklıktaki çözünürlüğü kaç g/100 g sudur?', '30', ['23', '100', '130'], '130 g çözeltide 30 g çözünen ve 100 g su vardır. Çözünürlük 30 g/100 g sudur.'),
  ('Kristallenme sırasında çözeltiden ayrılan katının saf olmasında en çok hangi uygulama etkilidir?', 'Çözeltinin yavaş soğutulması', ['Çözeltinin hızla dondurulması', 'Çözeltiye aşırı karıştırma yapılması', 'Çözeltinin hızla kaynatılması'], 'Yavaş kristallenmede iyonlar düzenli şekilde örgüye yerleşir ve safsızlıklar çözeltide kalır. Hızlı soğutma safsızlık hapsedebilir.'),
  ('Kristallendirmeyle saflaştırılan katının, sonunda az miktarda soğuk çözücüyle yıkanmasının nedeni nedir?', 'Yüzeydeki safsızlık içeren çözeltiyi uzaklaştırırken çok az kristalin çözünmesi', ['Kristalleri çözmek', 'Kristalleri ısıtmak', 'Kristalleri renklendirmek'], 'Soğuk çözücüde çözünürlük düşüktür; yüzeydeki ana çözeltiyi uzaklaştırır ve kristal kaybı az olur.'),
  ('1 atm\'de 100,78 °C\'de kaynayan tam ayrışmış sulu CaCl₂ çözeltisinin molalitesi kaçtır? (Kk = 0,52)', '0,5 m', ['0,25 m', '1,5 m', '0,17 m'], 'ΔTk = 0,78 °C = 0,52 × m × 3 denkleminden m = 0,5 mol/kg bulunur.'),
  ('Bilinmeyen bir çözücüde iyonlaşmayan bir maddenin 0,5 molal çözeltisi, çözücünün donma noktasını 2,5 °C düşürüyor. Çözücünün Kd değeri kaç °C·kg/mol\'dür?', '5,0', ['1,25', '2,5', '0,2'], 'ΔT = Kd · m olduğundan Kd = 2,5 / 0,5 = 5,0 °C·kg/mol\'dür.'),
  ('0,6 molal NaCl çözeltisinin (tam ayrışma varsayımıyla) donma noktası yaklaşık kaç °C\'dir? (Kd = 1,86)', '−2,23', ['−1,12', '−0,560', '−3,72'], 'i = 2, m = 0,6 olduğundan ΔT = 1,86 × 0,6 × 2 ≈ 2,23 °C\'dir. Gerçek deniz suyunda iyon etkileşimleri nedeniyle değer biraz daha küçüktür.'),
  ('Aynı koşullarda iki çözelti: birinde 0,3 mol glikoz, diğerinde 0,1 mol Na₃PO₄, her biri 1 kg suda çözülmüştür. Donma noktaları için hangisi doğrudur? (Tam ayrışma)', 'Na₃PO₄ çözeltisi daha düşük sıcaklıkta donar', ['Glikoz çözeltisi daha düşük sıcaklıkta donar, çünkü daha kütlelidir', 'İkisi aynı sıcaklıkta donar', 'İkisi de donmaz'], 'Etkin tanecik: glikoz için 0,3 mol, Na₃PO₄ için 0,4 mol. Daha büyük etkin molalite daha düşük donma noktası verir.'),
  ('Saf suyun Kk = 0,52 ve Kd = 1,86 °C·kg/mol olduğuna göre aynı sulu çözelti için ΔTk / ΔTd oranı yaklaşık kaçtır?', '0,28', ['0,520', '3,6', '1,0'], 'Aynı m ve i için ΔTk / ΔTd = Kk / Kd = 0,52 / 1,86 ≈ 0,28\'dir.'),
  ('Bir sulu çözeltinin donma noktası alçalması, kaynama noktası yükselmesinden neden daha büyüktür?', 'Suyun Kd değerinin Kk değerinden büyük olması', ['Çözeltinin yoğunluğunun büyük olması', 'Donma olayının ısı vermesi', 'Suyun buhar basıncının kaynama noktasında çok yüksek olması'], 'Aynı çözeltide ΔTd = Kd·m·i, ΔTk = Kk·m·i\'dir. Suda Kd = 1,86 ve Kk = 0,52 olduğundan donma noktası değişimi daha büyüktür.'),
  ('1901\'de ilk Nobel Kimya Ödülü\'nü, çözeltilerde kimyasal dinamik ve ozmotik basınç yasalarının keşfi nedeniyle kazanan bilim insanı kimdir?', 'Jacobus Henricus van\'t Hoff', ['Svante Arrhenius', 'Wilhelm Ostwald', 'Marie Curie'], 'Hollandalı kimyager van\'t Hoff, çözeltilerin ozmotik basıncının ideal gaz yasasına benzer bir bağıntıyı izlediğini göstermiştir.'),
  ('Tuzların suda iyonlarına ayrışarak elektrik ileten çözeltiler oluşturduğunu savunan elektrolitik ayrışma kuramı ile 1903 Nobel Kimya Ödülü\'nü kazanan bilim insanı kimdir?', 'Svante Arrhenius', ['Jacobus van\'t Hoff', 'Michael Faraday', 'Linus Pauling'], 'İsveçli kimyager Arrhenius, elektrolitlerin çözeltide iyonlara ayrıştığını öne sürmüş ve çalışmasıyla 1903 Nobel Kimya Ödülü\'nü almıştır.'),
  ('0,1 M Na⁺ ve 0,05 M Ca²⁺ iyonları içeren, anyon olarak yalnızca Cl⁻ bulunduran bir çözeltide Cl⁻ derişimi kaç M\'dır?', '0,2', ['0,15', '0,1', '0,3'], 'Çözelti elektriksel olarak nötrdür. Pozitif yük derişimi 0,1 + 2 × 0,05 = 0,2 M olduğundan Cl⁻ derişimi 0,2 M olmalıdır.'),
  ('Elektrolit çözeltisinin sıcaklığı artırıldığında elektrik iletkenliği genelde nasıl değişir?', 'Artar; çünkü iyonların hareketliliği artar', ['Azalır; çünkü iyonlar yok olur', 'Değişmez', 'Sıfıra iner'], 'Isınınca viskozite azalır ve iyonlar daha hızlı hareket eder; çözeltilerin iletkenliği artar. Metallerde ise sıcaklıkla iletkenlik azalır.'),
  ('Fraksiyonlu damıtma kolonundaki plaka (tepsi) sayısı artırıldığında ayırma verimi nasıl değişir?', 'Artar; çünkü buharlaşma-yoğunlaşma basamakları çoğalır', ['Azalır; çünkü karışım soğur', 'Değişmez; çünkü kaynama noktaları aynıdır', 'Sıfıra iner; çünkü bileşenler karışır'], 'Her plakada buhar ve sıvı yeniden dengeye gelir ve daha uçucu bileşen biraz daha zenginleşir. Plaka sayısı arttıkça bileşenler daha iyi ayrılır.'),
  ('Isıya duyarlı organik bir maddeyi bozmadan damıtmak için hangi yöntem uygundur?', 'Basıncı düşürerek (vakum altında) damıtmak', ['Basıncı artırarak damıtmak', 'Kuru buharla yakmak', 'Çözücüyü dondurarak damıtmak'], 'Dış basınç düşürülünce sıvı daha düşük sıcaklıkta kaynar. Isıya duyarlı madde yüksek sıcaklığa çıkarılmadan buharlaştırılır.'),
  ('İdeal iki bileşenli bir sıvı karışımında toplam buhar basıncı, sıvıdaki bir bileşenin mol kesriyle nasıl değişir?', 'Doğrusal olarak', ['Üstel olarak', 'Karesel olarak artarak', 'Hiç değişmez'], 'P = X_A · P°_A + (1 − X_A) · P°_B ifadesi X_A\'nın doğrusal bir fonksiyonudur.'),
  ('Jelatinin sıcak suda çözelti (sol), soğuyunca jel hâline gelmesi neyi gösterir?', 'Koloit hâllerinin sıcaklığa bağlı olarak değişebileceğini', ['Jelatinin yandığını', 'Jelatinin elementlerine ayrıştığını', 'Jelatinin iyonlaştığını'], 'Sıcakta jelatin zincirleri hareketlidir ve sıvı içinde dağılır. Soğuyunca zincirler ağ oluşturup suyu hapseder ve jel oluşur.'),
  ('Kauçuk ağacından alınan lateksin asit eklenince pıhtılaşıp katılaşması neyle açıklanır?', 'Koloit taneciklerinin yükünün nötrleşerek birleşmesiyle', ['Latekste suyun buharlaşmasıyla', 'Kauçuğun asitte erimesiyle', 'Asitin lateksle gaz üretmesiyle'], 'Latekste yüklü kauçuk parçacıkları kararlıdır. Asit eklenince yükler nötrleşir, parçacıklar birleşir ve kauçuk pıhtılaşır.'),
  ('Ultrafiltrasyon yöntemiyle koloit parçacıklarının sıvıdan ayrılabilmesi için filtre gözenekleri hangi ölçüde olmalıdır?', 'Koloit boyutuyla uyumlu çok küçük gözenekler', ['Gözlerle görülebilen büyük ve geniş gözenekler', 'Hiç gözenek bulunmayan yapı', 'Kum tanelerinden büyük gözenekler'], 'Normal filtre kâğıdı koloidi geçirir. Ultrafiltrasyonda gözenekler nanometre ölçeğinde olup koloit parçacıklarını tutar.'),
  ('Emülsiyonları kararlı hâle getiren emülgatör molekülleri için hangi yapısal özellik gereklidir?', 'Bir ucunun polar (suyu seven), diğer ucunun apolar (yağı seven) olması', ['Tamamen polar olması', 'Tamamen iyonik olması', 'Gaz hâlinde olması'], 'Çift karakterli yapı sayesinde molekül, yağ-su ara yüzeyinde yönelir ve damlacıkların birleşmesini önleyen koruyucu bir tabaka oluşturur.'),
  ('Aşağıdakilerden hangisi katı içinde sıvı dağılımına (katı emülsiyon/jel) örnektir?', 'Peynir', ['Sis', 'Köpük', 'Duman'], 'Peynirde sıvı fazlar katı protein ağında dağılmış durumdadır. Sis ve duman aerosol, köpük gaz-sıvı sistemdir.'),
  ('Basit damıtma ile iki sıvı birbirinden yeterince ayrılabilsin diye kaynama noktaları arasındaki fark yaklaşık ne olmalıdır?', 'Yaklaşık 25 °C veya daha fazla', ['Yaklaşık 1 °C', 'Hiç fark olmaması', 'Tam olarak 0,1 °C'], 'Fark çok küçükse buharda her iki bileşen de önemli miktarda bulunur ve basit damıtmayla ayrılamaz. Yaklaşık 25 °C fark genellikle yeterlidir.'),
  ('Derişik HCl şişesinin kapağı açıldığında şişe ağzında beyaz duman oluşmasının nedeni nedir?', 'Çözeltiden çıkan HCl gazının havadaki su buharıyla küçük asit damlacıkları oluşturması', ['Çözeltinin kaynayarak su buharı çıkarması', 'Sıvının donarak buz kristali oluşturması', 'Havanın içindeki azotun HCl ile tepkimesi'], 'Derişik HCl\'de çözünmüş gaz kısmi basıncı yüksektir; HCl buharı havadaki nemle birleşince asit damlacıkları (sis) görülür.'),
  ('Kütlece %30\'luk hidrojen peroksit çözeltisinden 100 g kütlece %3\'lük çözelti hazırlamak için kaç gram stok çözelti alınmalıdır?', '10', ['3', '30', '900'], 'Gerekli H₂O₂ 3 g\'dır. Stok çözeltide 3 g H₂O₂ bulunması için 3 / 0,30 = 10 g çözelti gerekir; kalan 90 g su eklenir.'),
  ('100 mL 0,1 M ile 200 mL 0,2 M aynı tür çözelti karıştırılıp üzerine 300 mL su ekleniyor. Son derişim yaklaşık kaç M\'dır?', '0,083', ['0,10', '0,20', '0,0500'], 'Toplam mol 0,01 + 0,04 = 0,05\'tir. Son hacim 0,6 L\'dir. Derişim 0,05 / 0,6 ≈ 0,083 M\'dır.'),
  ('Bir öğrenci kütlece yüzde ve yoğunluk verilen bir çözeltinin molaritesini hesaplamak için M = 10 · d · % / MA bağıntısını kullanıyor. Bağıntıdaki 10 çarpanı neden vardır?', 'Yüzdeyi bölme ve mL-L dönüşümü birleştiği için', ['Çözeltinin sıcaklığını düzeltmek için', 'Çözünenin yoğunluğunu 10 katına çıkarmak ve ölçmek için', 'Molaritenin birimini mol/mL yapmak için'], '1 L = 1000 mL ve % değeri 100\'e bölünür; 1000 / 100 = 10 çarpanı bu iki işlemin birleşimidir.'),
  ('200 mL 0,1 M Pb(NO₃)₂ ile 100 mL 0,4 M Na₂SO₄ çözeltileri karıştırılıyor. Oluşan PbSO₄ çökeleğinin kütlesi kaç gramdır? (PbSO₄: 303 g/mol)', '6,06', ['12,1', '3,030', '1,82'], 'Pb²⁺ 0,02 mol, SO₄²⁻ 0,04 moldür. Sınırlayıcı Pb²⁺\'dır; 0,02 × 303 = 6,06 g PbSO₄ çöker.'),
  ('1,17 g NaCl (58,5 g/mol) içeren çözeltiye fazla AgNO₃ eklendiğinde oluşan AgCl\'nin (143,5 g/mol) kütlesi kaç gramdır?', '2,87', ['1,17', '5,740', '1,43'], 'NaCl 0,02 moldür; 0,02 mol Cl⁻ 0,02 mol AgCl verir. Kütle 0,02 × 143,5 = 2,87 g\'dır.'),
  ('Derişimi tam bilinmeyen NaOH çözeltisi hazırlanırken önce yaklaşık derişimli çözelti yapılıp sonra standart asitle titre edilmesinin nedeni nedir?', 'NaOH\'nin tartım sırasında nem ve CO₂ çekmesi nedeniyle gerçek derişimin hesaplananla uyuşmaması', ['NaOH\'nin çok pahalı olması', 'NaOH\'nin saf suda çözünmemesi', 'Titrasyonun çözeltiyi donması'], 'Higroskopik NaOH\'nin tartılan kütlesi gerçek NaOH miktarını göstermez. Kesin derişim standart bir asitle titrasyonla belirlenir.'),
  ('18 g glikoz (180 g/mol) ile 90 g su (18 g/mol) karıştırılıyor. Glikozun mol kesri yaklaşık kaçtır?', '0,0196', ['0,10', '0,196', '0,00200'], 'Glikoz 0,1 mol, su 5 moldür. X(glikoz) = 0,1 / 5,1 ≈ 0,0196\'dır.'),
  ('Bir şişede eşit kütlelerde (46\'şar gram) etanol ve su bulunuyor. Etanol 46 g/mol, su 18 g/mol ise karışımda etanolün mol kesri yaklaşık kaçtır?', '0,28', ['0,50', '0,72', '0,140'], 'Etanol 1 mol, su 46 / 18 ≈ 2,56 moldür. X(etanol) = 1 / 3,56 ≈ 0,28\'dir.'),
  ('Kütlece %64 metanol içeren sulu çözeltide metanolün mol kesri kaçtır? (CH₃OH: 32 g/mol, H₂O: 18 g/mol)', '0,5', ['0,64', '0,36', '0,25'], '100 g çözeltide 64 g (2 mol) metanol ve 36 g (2 mol) su vardır. X(metanol) = 2 / 4 = 0,5\'tir.'),
  ('50 mL etanol ile 50 mL su karıştırıldığında toplam hacim yaklaşık kaç mL olur?', 'Yaklaşık 96-97 mL', ['Tam olarak 100 mL olur', 'Yaklaşık 103 mL', 'Yaklaşık 50 mL'], 'Etanol ve su molekülleri hidrojen bağlarıyla sıkı yerleştiğinden toplam hacim 100 mL\'den biraz küçük, yaklaşık 96-97 mL çıkar.'),
  ('14 ayar altından yapılmış 10 g\'lık bir yüzükte yaklaşık kaç gram saf altın bulunur?', '5,83', ['1,4', '7,500', '14'], '14 ayar, 24 ayarın 14 / 24\'ü yani yaklaşık %58,3 altındır. 10 g × 0,583 ≈ 5,83 g altın bulunur.'),
  ('Çözelti türlerinin çözünen ve çözücüsü eşleştirilirken hangisi yanlıştır?', 'Hava: gaz içinde katı', ['Soda: sıvı içinde gaz', 'Pirinç: katı içinde katı', 'Sirke: sıvı içinde sıvı'], 'Temiz hava gaz içinde gaz çözeltisidir; katı tanecikler içeren duman veya toz ise çözelti değil aerosoldür.'),
  ('Aynı sıcaklıkta aynı tür iki çözeltiden birinin yoğunluğu ötekinden büyükse, aşağıdakilerden hangisi genel olarak doğrudur?', 'Yoğunluğu büyük olan çözelti, aynı hacimde daha fazla çözünen içerir', ['Yoğunluğu büyük olan çözelti daha seyreltiktir', 'İki çözeltinin derişimi eşittir', 'Yoğunluk derişimle ilgisizdir'], 'Aynı çözünen ve çözücü için derişim arttıkça çözeltinin yoğunluğu genellikle artar; bu nedenle yoğunluk ölçümü derişim tahmininde kullanılır.'),
  ('Sulu bir tuz çözeltisi dondurulurken ortaya çıkan buzun yapısı için hangisi söylenebilir?', 'İlk oluşan buz büyük ölçüde saf sudur ve kalan çözelti daha derişik hâle gelir', ['Buz tuz iyonlarıyla aynı oranda oluşur', 'Buz yalnız tuzdan oluşur', 'Çözelti donmaz'], 'Buz kristalleri çözünen taneciği dışlar. Donma ilerledikçe kalan sıvı derişikleşir ve donma noktası düşer.'),
  ('Aküdeki sülfürik asit çözeltisinin yoğunluğu bir hidrometreyle ölçülür. Akü boşaldıkça yoğunluğun düşmesinin nedeni nedir?', 'Deşarjda H₂SO₄ tüketilir ve çözeltideki asit derişimi azalır', ['Aküdeki suyun buharlaşması', 'Asidin kurşuna dönüşmesi', 'Çözeltideki gazın artması'], 'Akü boşalırken sülfürik asit tepkimeye girerek PbSO₄ oluşturur. Asit derişimi azaldığından çözeltinin yoğunluğu düşer.'),
  ('Bir kimya laboratuvarında \'10 g şeker, 100 mL çözeltide\' ifadesi kütle/hacim %10\'dur. Çözeltinin yoğunluğu 1,04 g/mL ise kütlece (k/k) yüzdesi yaklaşık kaçtır?', '9,6', ['10', '10,4', '8,5'], '100 mL çözelti 104 g\'dır. Kütlece yüzde 10 / 104 × 100 ≈ 9,6\'dır.'),
  ('Kütlece %10\'luk 200 g ve %20\'lik 300 g tuz çözeltileri karıştırılıp 100 g su buharlaştırılıyor. Son çözeltinin kütlece yüzdesi kaçtır?', '20', ['160', '25', '15'], 'Tuz 20 + 60 = 80 g\'dır. Toplam kütle 500 − 100 = 400 g olduğundan yüzde 80 / 400 × 100 = 20\'dir.'),
  ('Sıcak havalarda kapalı bir plastik şişedeki gazlı içeceğin kapağını açınca fışkırma olmasının nedeni aşağıdakilerden hangisidir?', 'Sıcaklık artınca CO₂ çözünürlüğünün azalması ve basıncın yükselmesi', ['İçecekteki şekerin gaz çıkarması', 'Su moleküllerinin parçalanması', 'Şişenin içindeki oksijenin artması'], 'Isınmayla CO₂ çözünürlüğü düşer; gaz fazı basıncı artar. Kapak açılınca basınç düşer ve çözeltiden ayrılan gaz sıvıyı dışarı iter.'),
  ('Aktif karbonun sudaki renk veren kirleticileri tutma yeteneğinin yüksek olması, koloit özelliklerinden hangisiyle ilgilidir?', 'Çok büyük yüzey alanı sayesinde adsorpsiyon gücüyle', ['Düşük yoğunluğuyla', 'Yüksek kaynama noktasıyla', 'İyonik yapısıyla'], 'Aktif karbon çok gözenekli olup birim kütlede çok büyük yüzey alanı sunar; kirletici moleküller bu yüzeyde tutunur.'),
  ('Normal koşullarda (NK) 2,24 L HCl gazı suda çözünüp hacim 500 mL\'ye tamamlanıyor. Çözeltideki HCl derişimi kaç M\'dır?', '0,2', ['0,10', '0,4', '2,0'], '2,24 L HCl NK\'de 0,1 mol\'dür. Derişim 0,1 / 0,5 = 0,2 M\'dır.'),
  ('NK\'de 4,48 L NH₃ gazı suda çözülerek 2 L çözelti hazırlanıyor. NH₃ derişimi kaç M\'dır?', '0,1', ['0,2', '0,05', '1,0'], '4,48 L NH₃ NK\'de 0,2 mol\'dür. Derişim 0,2 / 2 = 0,1 M\'dır.'),
  ('Kütlece %17\'lik, yoğunluğu 0,93 g/mL olan amonyak çözeltisinin (NH₃: 17 g/mol) molaritesi kaçtır?', '9,3 M', ['0,93 M', '17 M', '5,5 M'], 'M = 10 · % · d / MA = 10 · 17 · 0,93 / 17 = 9,3 M\'dır.'),
  ('0,15 M NaCl çözeltisinin 200 mL\'sinde kaç gram Na⁺ iyonu bulunur? (Na: 23 g/mol)', '0,69', ['0,35', '6,9', '1,380'], 'NaCl 0,03 mol, Na⁺ da 0,03 moldür. Kütle 0,03 × 23 = 0,69 g\'dır.'),
  ('1 L 0,2 M şeker çözeltisinden 400 mL dökülüp yerine 400 mL saf su ekleniyor. Yeni derişim kaç M\'dır?', '0,12', ['0,080', '0,2', '0,16'], 'Kalan 600 mL\'de 0,12 mol şeker vardır. Su eklenince hacim 1 L olur; derişim 0,12 M\'dır.'),
  ('Aynı sıcaklıkta A tuzunun çözünürlüğü 10 g/100 g su, B tuzunun 30 g/100 g sudur. 200 g suya 25 g A ve 25 g B konup karıştırılıyor (ortak iyon yok). Çözeltide çözünmeden kalan katı hangisidir?', 'Yalnız A\'dan 5 g', ['Yalnız B\'den 5 g', 'A\'dan ve B\'den birer miktar', 'Hiçbir katı kalmaz'], '200 g su 20 g A ve 60 g B çözebilir. A için 5 g çözünmeden kalır; B\'nin tamamı çözünür.'),
  ('Bir çözeltinin molaritesini ve yoğunluğunu bilen bir öğrenci, 1 L çözeltideki çözücü kütlesini nasıl bulur?', 'Çözelti kütlesinden (1000·d) çözünen kütlesini çıkararak', ['Çözelti hacminden çözünen mol sayısını çıkararak bulunur ve ölçülür', 'Yoğunluğu molariteyle çarparak', 'Çözünenin yoğunluğunu 1000\'e bölerek'], '1 L çözeltinin kütlesi 1000 · d gramdır. Çözünen kütlesi (M · MA) çıkarılınca çözücü kütlesi bulunur; bu molalite hesabında kullanılır.'),
  ('Şeker ve tuzun karışımından önce suda çözünme, ardından suyun buharlaştırılması işlemleri uygulanıyor. Bu işlemlerle iki maddeyi ayrı ayrı elde edebilir miyiz?', 'Hayır; ikisi de suda çözündüğünden bu yolla ayrılamazlar', ['Evet; şeker önce kristallenir', 'Evet; tuz önce buharlaşır', 'Evet; çünkü ikisi gaz çıkarır'], 'Hem şeker hem tuz suda çözünür. Su buharlaştırıldığında ikisi birlikte kalır. Ayrım için başka bir özellik (örneğin alkolde çözünürlük farkı) kullanılmalıdır.'),
  ('Bir tuz çözeltisinin kaynama sıcaklığının 100 °C\'nin üstünde olması, çözeltinin buhar basıncı için hangi sonucu ifade eder?', '100 °C\'de çözeltinin buhar basıncının 1 atm\'den düşük olduğunu', ['100 °C\'de çözeltinin buhar basıncının 1 atm\'den yüksek olduğunu', 'Çözeltinin hiç buharlaşmadığını', 'Çözeltinin buhar basıncının saf suyunkine eşit olduğunu'], 'Kaynama için buhar basıncı dış basınca eşit olmalıdır. Çözelti 100 °C\'de kaynamadığına göre bu sıcaklıkta basıncı 1 atm\'den düşüktür.'),
  ('Bir termik ya da nükleer santralin ısınmış soğutma suyunun doğrudan göle verilmesi, sudaki canlılar için hangi nedenle tehlikelidir?', 'Sıcaklık artışının suda çözünmüş oksijen miktarını azaltması', ['Suyun yoğunluğunun sıfıra inmesi', 'Su içindeki tuzların tamamen çökmesi', 'Suyun basıncının atmosfer basıncına eşitlenmesi'], 'Gazların sudaki çözünürlüğü sıcaklıkla azalır. Isınan gölde çözünmüş oksijen düşer ve balıklar zarar görür.'),
  ('Etilen glikol zehirli olduğundan bazı soğutma sıvılarında yerine gıda katkı maddesi olarak da kullanılan, daha az zehirli antifriz olarak hangi madde tercih edilir?', 'Propilen glikol', ['Metanol', 'Hidrazin', 'Amonyak'], 'Propilen glikol, etilen glikole göre çok daha düşük zehirlidir ve donma noktasını benzer biçimde düşürür.'),
  ('Yoğunluğu 1,025 g/mL olan ve kütlece %3,5 tuz içeren deniz suyunun 1 m³\'ünde yaklaşık kaç kg tuz bulunur?', '35,9', ['35', '3,590', '359'], '1 m³ deniz suyunun kütlesi 1025 kg\'dır. Tuz kütlesi 1025 × 0,035 ≈ 35,9 kg\'dır.'),
  ('250 mL 0,2 M şeker çözeltisinin sıcaklığı artırıldığında hacmi biraz genleşirse molaritesi ve molalitesi nasıl değişir?', 'Molarite küçülür, molalite değişmez', ['Molalite küçülür, molarite değişmez', 'İkisi de büyür', 'İkisi de değişmez'], 'Hacim arttığı için mol/L küçülür; çözücü kütlesi ise sabit kaldığından molalite değişmez.'),
  ('Bir çözeltideki çözünen tanecik sayısı sabitken, çözücü miktarı artırılırsa aşağıdaki koligatif özelliklerden hangisi azalır?', 'Donma noktasındaki alçalma miktarı', ['Çözeltideki çözünen taneciklerinin toplam sayısı', 'Çözücünün saf hâldeki donma noktası', 'Suyun kaynama noktası sabiti Kk'], 'Çözücü artınca molalite küçülür; ΔTd = Kd·m·i olduğundan donma noktası alçalması azalır. Kk ve saf çözücünün donma noktası çözücüye özgüdür.'),
];
